SELECT gen_random_uuid(), 'article', 0, 'hello-world', 'About', 'HI!! I believe that my education will make me a very competitive candidate for a Oracle Database 10gR2/ oracle EBS R12 administration position. The key strengths that I possess for success in this position include: * I had successfully been implementing multiple projects using Oracle EBS R12 for…', '{"type":"none"}'::jsonb, '[{"type":"heading","level":2,"text":"HI!!"},{"type":"paragraph","text":"I believe that my education will make me a very competitive candidate for a Oracle Database 10gR2/ oracle EBS R12 administration position. The key strengths that I possess for success in this position include:"},{"type":"paragraph","text":"* I had successfully been implementing multiple projects using Oracle EBS R12 for conacent consulting pvt. Ltd. AND worked with Collabera for IBM till nov 2015.\n* I am a hard worker and fast learner\n* I strive for continued excellence"},{"type":"paragraph","text":"With a MCA degree in Computer Programming and system/database administration, I have good understanding of software development project. I also have experience in learning and excelling at new technologies as needed."},{"type":"paragraph","text":"Please see my resume for additional information on my experience."},{"type":"paragraph","text":"I can be reached anytime. Thank you for your time and consideration. I look forward to speaking with you about any opportunity."},{"type":"paragraph","text":"Sincerely,"},{"type":"paragraph","text":"Sayantan Chakraborty"}]'::jsonb,
