SELECT gen_random_uuid(), 'page', 1, 'ssh-passwordless-login', 'ssh passwordless login', 'this way i have avoided PRVF-4007 [oracle1@rac-2 ~]$ mkdir ~/.ssh mkdir: cannot create directory `/home/oracle1/.ssh’: File exists [oracle1@rac-2 ~]$ ping rac-1 PING rac-1.sayantan-chakraborty.de (192.168.1.2) 56(84) bytes of data. 64 bytes from rac-1.sayantan-chakraborty.de (192.168.1.2)…', '{"type":"none"}'::jsonb, '[{"type":"html","html":"<p>this way i have avoided \t <strong>PRVF-4007</strong></p>"},{"type":"quote","text":"[oracle1@rac-2 ~]$ mkdir ~/.ssh\nmkdir: cannot create directory `/home/oracle1/.ssh'': File exists\n[oracle1@rac-2 ~]$ ping rac-1\nPING rac-1.sayantan-chakraborty.de (192.168.1.2) 56(84) bytes of data.\n64 bytes from rac-1.sayantan-chakraborty.de (192.168.1.2): icmp_seq=1 ttl=64 time=0.301 ms\n64 bytes from rac-1.sayantan-chakraborty.de (192.168.1.2): icmp_seq=2 ttl=64 time=0.218 ms\n64 bytes from rac-1.sayantan-chakraborty.de (192.168.1.2): icmp_seq=3 ttl=64 time=0.342 ms\n64 bytes from rac-1.sayantan-chakraborty.de (192.168.1.2): icmp_seq=4 ttl=64 time=0.341 ms\n[1]+ Stopped ping rac-1\n[oracle1@rac-2 ~]$ ping rac-1-priv\nPING rac-1-priv.sayantan-chakraborty.de (192.168.181.10) 56(84) bytes of data.\n64 bytes from rac-1-priv.sayantan-chakraborty.de (192.168.181.10): icmp_seq=1 ttl=64 time=3.12 ms\n64 bytes from rac-1-priv.sayantan-chakraborty.de (192.168.181.10): icmp_seq=2 ttl=64 time=1.46 ms\n64 bytes from rac-1-priv.sayantan-chakraborty.de (192.168.181.10): icmp_seq=3 ttl=64 time=1.47 ms\n64 bytes from rac-1-priv.sayantan-chakraborty.de (192.168.181.10): icmp_seq=4 ttl=64 time=1.48 ms\n[2]+ Stopped ping rac-1-priv\n[oracle1@rac-2 ~]$ chmod 700 ~/.ssh\n[oracle1@rac-2 ~]$ /usr/bin/ssh-keygen -t dsa\nGenerating public/private dsa key pair.\nEnter file in which to save the key (/home/oracle1/.ssh/id_dsa):\n/home/oracle1/.ssh/id_dsa already exists.\nOverwrite (y/n)? y\nEnter passphrase (empty for no passphrase):\nEnter same passphrase again:\nYour identification has been saved in /home/oracle1/.ssh/id_dsa.\nYour public key has been saved in /home/oracle1/.ssh/id_dsa.pub.\nThe key fingerprint is:\n35:d1:3a:65:b7:70:7f:2f:d2:ec:44:f1:40:bd:f6:5e oracle1@rac-2.sayantan-chakraborty.de\n[oracle1@rac-2 ~]$ touch ~/.ssh/authorized_keys\n[oracle1@rac-2 ~]$ ls -l ~/.ssh\ntotal 20\n-rw------- 1 oracle1 oinstall 3044 Feb 21 17:16 authorized_keys\n-rw------- 1 oracle1 oinstall 668 Feb 21 17:16 id_dsa\n-rw-r--r-- 1 oracle1 oinstall 627 Feb 21 17:16 id_dsa.pub\n-rw-r--r-- 1 oracle1 oinstall 6886 Feb 21 01:29 known_hosts\n[oracle1@rac-2 ~]$ ssh rac-1 cat ~/.ssh/id_dsa.pub >> ~/.ssh/authorized_key\noracle1@rac-1''s password:\n[oracle1@rac-2 ~]$ ssh rac-2 cat ~/.ssh/id_dsa.pub >> ~/.ssh/authorized_keys\noracle1@rac-2''s password:\n[oracle1@rac-2 ~]$ ls -l ~/.ssh\ntotal 24\n-rw-r--r-- 1 oracle1 oinstall 627 Feb 21 17:17 authorized_key\n-rw------- 1 oracle1 oinstall 3671 Feb 21 17:17 authorized_keys\n-rw------- 1 oracle1 oinstall 668 Feb 21 17:16 id_dsa\n-rw-r--r-- 1 oracle1 oinstall 627 Feb 21 17:16 id_dsa.pub\n-rw-r--r-- 1 oracle1 oinstall 6886 Feb 21 01:29 known_hosts\n[oracle1@rac-2 ~]$ scp ~/.ssh/authorized_keys rac-1:.ssh/authorized_keys\noracle1@rac-1''s password:\nauthorized_keys 100% 3671 3.6KB/s 00:00\n[oracle1@rac-2 ~]$\n[oracle1@rac-2 ~]$ chmod 600 ~/.ssh/authorized_keys\n[oracle1@rac-2 ~]$ ssh rac-1 \"date;hostname\"\nSun Feb 21 17:18:23 IST 2010\nrac-1.sayantan-chakraborty.de\n[oracle1@rac-2 ~]$ ssh rac-2 \"date;hostname\"\nSun Feb 21 17:19:32 IST 2010\nrac-2.sayantan-chakraborty.de\n[oracle1@rac-2 ~]$"}]'::jsonb,
