SELECT gen_random_uuid(), 'page', 3, 'runcluvfy-sh', 'runcluvfy.sh', 'you must have user equivalence in all nodes. [oracle1@rac-2 ~]$ ./runcluvfy.sh stage -pre crsinst -n rac-1,rac-2 -fixup -verbose > ~/clu.txt output Performing pre-checks for cluster services setup Checking node reachability… Check: Node reachability from node “rac-2” Destination Node Reachable?…', '{"type":"none"}'::jsonb, '[{"type":"html","html":"<p><strong>you must have user equivalence in all nodes.</strong></p>"},{"type":"quote","text":"[oracle1@rac-2 ~]$ ./runcluvfy.sh stage -pre crsinst -n rac-1,rac-2 -fixup -verbose > ~/clu.txt"},{"type":"paragraph","text":"output"},{"type":"quote","text":"Performing pre-checks for cluster services setup\nChecking node reachability...\nCheck: Node reachability from node \"rac-2\"\nDestination Node Reachable?\n------------------------------------ ------------------------\nrac-2 yes\nrac-1 yes\nResult: Node reachability check passed from node \"rac-2\"\nChecking user equivalence...\nCheck: User equivalence for user \"oracle1\"\nNode Name Comment\n------------------------------------ ------------------------\nrac-2 passed\nrac-1 passed\nResult: User equivalence check passed for user \"oracle1\"\nChecking node connectivity...\nChecking hosts config file...\nNode Name Status Comment\n------------ ------------------------ ------------------------\nrac-2 passed\nrac-1 passed\nVerification of the hosts config file successful\nInterface information for node \"rac-2\"\nName IP Address Subnet Gateway Def. Gateway HW Address MTU\n------ --------------- --------------- --------------- --------------- ----------------- ------\neth0 192.168.1.3 192.168.1.0 0.0.0.0 192.168.1.1 00:1D:72:39:3A:E4 1500\nvirbr0 192.168.122.1 192.168.122.0 0.0.0.0 192.168.1.1 00:00:00:00:00:00 1500\neth2 192.168.181.20 192.168.181.0 0.0.0.0 192.168.1.1 00:00:00:00:00:00 1500\nInterface information for node \"rac-1\"\nName IP Address Subnet Gateway Def. Gateway HW Address MTU\n------ -----------