SELECT gen_random_uuid(), 'page', 6, 'way-to-avoiding-prv-4007-in-runcluvfy-sh', 'Way To Avoid PRV-4007 For “runcluvfy.sh”', 'I encountered a problem eg. Result: PRVF-4007 : User equivalence check failed for [oracle@rac-2 grid]$ ./runcluvfy.sh stage -pre crsinst -n rac-1,rac-2 -fixup -verbose Performing pre-checks for cluster services setup Checking node reachability… Check: Node reachability from node “rac-2”…', '{"type":"none"}'::jsonb, '[{"type":"paragraph","text":"I encountered a problem eg. Result: PRVF-4007 : User equivalence check failed for"},{"type":"quote","text":"[oracle@rac-2 grid]$ ./runcluvfy.sh stage -pre crsinst -n rac-1,rac-2 -fixup -verbose\nPerforming pre-checks for cluster services setup\nChecking node reachability…\nCheck: Node reachability from node “rac-2”\nDestination Node Reachable?\n———————————— ————————\nrac-2 yes\nrac-1 yes\nResult: Node reachability check passed from node “rac-2”\nChecking user equivalence…\nCheck: User equivalence for user “oracle”\nNode Name Comment\n———————————— ————————\nrac-2 failed\nrac-1 failed\nResult: PRVF-4007 : User equivalence check failed for user “oracle”\nERROR:\nUser equivalence unavailable on all the specified nodes\nVerification cannot proceed\nPre-check for cluster services setup was unsuccessful on all the nodes.\n[oracle@rac-2 grid]$"},{"type":"paragraph","text":"Here is a suggested method that may help you."},{"type":"html","html":"<p><strong>steps to avoid PRV-4007</strong></p>"},{"type":"paragraph","text":"you can take either of 1) and 2)\n1) just del all previous user and create all new user in each node.If it is possible run telnet with each node and create group and users with same uid and gid."},{"type":"paragraph","text":"I used step 1 and step 3 both to recover myself from this error."},{"type":"paragraph","text":"2) if you have initially created a user one or two groups are not matching you can do it easily.but if your uid do not match for grid and oracle user,you may face some problem. But step 2 is the easiest way to handle this stuff."},{"type":"paragraph","text":"first issue :"},{"type":"quote","text":"usermod -u 503 grid"},{"type":"paragraph","text":"Then"},{"type":"quote","text":"# /bin/find / -uid -print0 | /usr/bin/xargs -0 -r /bin/chown"},{"type":"paragraph","text":"if you do not issue the above command you may face error :"},{"type":"quote","text":"GConf error: Failed to contact configuration server; some possible causes are that you need to enable TCP/IP networking for ORBit, or you have stale NFS locks due to a system crash. See http://www.gnome.org/projects/gconf/ for information. (Details - 1: IOR file ''/tmp/gconfd-grid/lock/ior'' not opened successfully, no gconfd located: No such file or directory 2: IOR file ''/tmp/gconfd-root/lock/ior'' not opened successfully, no gconfd located: No such file or directory)"},{"type":"html","html":"<p><strong>key idea to issue the above command is:<br>\n</strong></p>"},{"type":"paragraph","text":"The user needs to be logged off when making this type of change.\nThe usermod(8) just updates the /etc/group files. It is your responsibility to change the ownership of any files owned by that user, including their home directory, its files, and any files they may own anywhere in the file system."},{"type":"html","html":"<p><strong>Step 3)</strong><br>\n<a href=\"/11gr2-rac-installation/ssh-passwordless-login\">ssh configuration for password less login</a></p>"},{"type":"html","html":"<p><strong>NB:-</strong><br>\nyou need to follow either of steps 1 and steps 2 and then steps 3.This steps 3 is mandatory.</p>"}]'::jsonb,
  NULL, 'csayantan', '{}'::text[], '{}'::text[], '{"title":"Way To Avoid PRV-4007 For “runcluvfy.sh”","description":"I encountered a problem eg. Result: PRVF-4007 : User equivalence check failed for [oracle@rac-2 grid]$ ./runcluvfy.sh stage -pre crsinst -n rac-1,rac-2 -fixup…","canonical":"https://cadentic.dev/11gr2-rac-installation/way-to-avoiding-prv-4007-in-runcluvfy-sh","noindex":false}'::jsonb, 'draft', NULL,
  '2010-02-27T06:49:13Z'::timestamptz, 'wordpress', '82', now(), now()
