SELECT gen_random_uuid(), 'page', 0, 'undo-tbs', 'undo-tbs', 'SQL> show parameter undo_ NAME TYPE VALUE ———————————— ———– —————————— undo_management string AUTO undo_retention integer 900 undo_tablespace string UNDOTBS1 SQL> create rollback segment r1; Rollback segment created. SQL> show parameter undo_sup SQL> show parameter undo_ NAME TYPE VALUE…', '{"type":"none"}'::jsonb, '[{"type":"quote","text":"SQL> show parameter undo_\nNAME TYPE VALUE\n------------------------------------ ----------- ------------------------------\nundo_management string AUTO\nundo_retention integer 900\nundo_tablespace string UNDOTBS1\nSQL> create rollback segment r1;\nRollback segment created.\nSQL> show parameter undo_sup\nSQL> show parameter undo_\nNAME TYPE VALUE\n------------------------------------ ----------- ------------------------------\nundo_management string AUTO\nundo_retention integer 900\nundo_tablespace string UNDOTBS1"},{"type":"paragraph","text":"There is no undo_suppress_error parameter in 10g."},{"type":"quote","text":"SQL> alter system set undo_suppress_errors=true;\nalter system set undo_suppress_errors=true\n*\nERROR at line 1:\nORA-25138: UNDO_SUPPRESS_ERRORS initialization parameter has been made obsolete"},{"type":"html","html":"<p>let us see the undo_retention policy initialization.<br>\n<code></code></p>"},{"type":"quote","text":"SQL>\nSQL> alter system set undo_retention 1000;\nalter system set undo_retention 1000\n*\nERROR at line 1:\nORA-00927: missing equal sign\nSQL> alter system set undo_retention=1000;\nSystem altered."},{"type":"html","html":"<p>viewing v$undostat.<br>\n<code></code></p>"},{"type":"quote","text":"SQL>\nSQL> select end_time,begin_time,undoblks from v$undostat;\nEND_TIME BEGIN_TIM UNDOBLKS\n--------- --------- ----------\n18-JUN-09 18-JUN-09 3\n18-JUN-09 18-JUN-09 0\n18-JUN-09 18-JUN-09 2\n18-JUN-09 18-JUN-09 0\n18-JUN-09 18-JUN-09 12\nSQL>\nC:\\Documents and Settings\\exam>set nls_date_format=dd-mm-yy:hh24:mi:ss\nSQL> select end_time,begin_time,undoblks from v$undostat;\nEND_TIME BEGIN_TIME UNDOBLKS\n----------------- ----------------- ----------\n18-06-09:11:46:59 18-06-09:11:40:53 3\n18-06-09:11:40:53 18-06-09:11:30:53 0\n18-06-09:11:30:53 18-06-09:11:20:53 2\n18-06-09:11:20:53 18-06-09:11:10:53 0\n18-06-09:11:10:53 18-06-09:11:00:53 12\nSQL>\nSQL> select to_char(begin_time, ''DD-MON-RR HH24:MI'') begin_time,\n2 to_char(end_time, ''DD-MON-RR HH24:MI'') end_time, tuned_undoretention\n3 from v$undostat order by end_time;\nBEGIN_TIME END_TIME TUNED_UNDORETENTION\n--------------- --------------- -------------------\n18-JUN-09 11:00 18-JUN-09 11:10 900\n18-JUN-09 11:10 18-JUN-09 11:20 900\n18-JUN-09 11:20 18-JUN-09 11:30 1000\n18-JUN-09 11:30 18-JUN-09 11:40 1000\n18-JUN-09 11:40 18-JUN-09 11:50 1000\nSQL>"}]'::jsonb,
  NULL, 'csayantan', '{}'::text[], '{}'::text[], '{"title":"undo-tbs","description":"SQL> show parameter undo_ NAME TYPE VALUE ———————————— ———– —————————— undo_management string AUTO undo_retention integer 900 undo_tablespace string UNDOTBS1…","canonical":"https://cadentic.dev/oca-ocp-10g-class-notes-and-practice/undo-tbs","noindex":false}'::jsonb, 'draft', NULL,
