SELECT gen_random_uuid(), 'page', 2, 'indexing-notes-9i', 'indexing-notes-9i', 'Microsoft Windows XP [Version 5.1.2600] (C) Copyright 1985-2001 Microsoft Corp. C:\Documents and Settings\new>sqlplus / as sysdba Usage: SQLPLUS [ [] [] [] ] where ::= -H | -V | [ [-M ] [-R ] [-S] ] ::= [/][@] | / | /NOLOG ::= @[.] [ …] “-H” displays the SQL*Plus version banner and usage syntax', '{"type":"none"}'::jsonb, '[{"type":"quote","text":"Microsoft Windows XP [Version 5.1.2600]\n(C) Copyright 1985-2001 Microsoft Corp.\nC:\\Documents and Settings\\new>sqlplus / as sysdba\nUsage: SQLPLUS [ [] [] [] ]\nwhere ::= -H | -V | [ [-M ] [-R ] [-S] ]\n::= [/][@] | / | /NOLOG\n::= @[.] [ ...]\n\"-H\" displays the SQL*Plus version banner and usage syntax\n\"-V\" displays the SQL*Plus version banner\n\"-M \" uses HTML markup options\n\"-R \" uses restricted mode\n\"-S\" uses silent mode\nC:\\Documents and Settings\\new>sqlplus \"/ as sysdba\"\nSQL*Plus: Release 9.0.1.0.1 - Production on Thu Apr 1 11:05:50 2010\n(c) Copyright 2001 Oracle Corporation. All rights reserved.\nERROR:\nORA-01031: insufficient privileges\nEnter user-name:\nERROR:\nORA-01017: invalid username/password; logon denied\nEnter user-name:\nERROR:\nORA-01017: invalid username/password; logon denied\nSP2-0157: unable to CONNECT to ORACLE after 3 attempts, exiting SQL*Plus\nC:\\Documents and Settings\\new>sqlplus \"sys/system as sysdba\"\nSQL*Plus: Release 9.0.1.0.1 - Production on Thu Apr 1 11:05:59 2010\n(c) Copyright 2001 Oracle Corporation. All rights reserved.\nConnected to:\nOracle9i Enterprise Edition Release 9.0.1.1.1 - Production\nWith the Partitioning option\nJServer Release 9.0.1.1.1 - Production\nSQL> show parameter create_bit\nNAME TYPE VALUE\n------------------------------------ ----------- ------------------------------\ncreate_bitmap_area_size integer 8388608\nSQL> show parameter workarea\nNAME TYPE VALUE\n------------------------------------ ----------- ------------------------------\nworkarea_size_policy string MANUAL\nSQL> show parameter pga_target\nSQL> show parameter pga\nNAME TYPE VALUE\n------------------------------------ ----------- ------------------------------\npga_aggregate_target big integer 0\nSQL> alter system set pga_aggregate_target=20M;\nSystem altered.\nSQL> show parameter pga\nNAME TYPE VALUE\n------------------------------------ ----------- ------------------------------\npga_aggregate_target big integer 20971520\nSQL> alter system set workare_size_policy=auto;\nalter system set workare_size_policy=auto\n*\nERROR at line 1:\nORA-02065: illegal option for ALTER SYSTEM\nSQL> alter system set workarea_size_policy=auto;\nSystem altered.\nSQL> show parameter pga\nNAME TYPE VALUE\n------------------------------------ ----------- ------------------------------\npga_aggregate_target big integer 20971520\nSQL> show parameter workarea\nNAME TYPE VALUE\n------------------------------------ ----------- ------------------------------\nworkarea_size_policy string AUTO\nSQL> show parameter create_bit\nNAME TYPE VALUE\n------------------------------------ ----------- ------------------------------\ncreate_bitmap_area_size integer 8388608\nSQL> select * from pgastats;\nselect * from pgastats\n*\nERROR at line 1:\nORA-00942: table or view does not exist\nSQL> select * from v$pgastats;\nselect * from v$pgastats\n*\nERROR at line 1:\nORA-00942: table or view does not exist\nSQL> select * from v$pgastat;\nNAME VALUE\n---------------------------------------------------------------- ----------\naggregate PGA auto target 12183552\nglobal memory bound 1024\ntotal expected memory 0\ntotal PGA inuse 7433216\ntotal PGA allocated 8049664\nmaximum PGA allocated 8049664\ntotal PGA used for auto workareas 0\nmaximum PGA used for auto workareas 0\ntotal PGA used for manual workareas 0\nmaximum PGA used for manual workareas 0\nestimated PGA memory for optimal 0\nNAME VALUE\n---------------------------------------------------------------- ----------\nmaximum PGA memory for optimal 0\nestimated PGA memory for one-pass 0\nmaximum PGA memory for one-pass 0\n14 rows selected.\nSQL> select * from v$pgastat;\nNAME VALUE\n---------------------------------------------------------------- ----------\naggregate PGA auto target 12045312\nglobal memory bound 1024\ntotal expected memory 0\ntotal PGA inuse 7580672\ntotal PGA allocated 8302592\nmaximum PGA allocated 8351744\ntotal PGA used for auto workareas 0\nmaximum PGA used for auto workareas 0\ntotal PGA used for manual workareas 0\nmaximum PGA used for manual workareas 0\nestimated PGA memory for optimal 0\nNAME VALUE\n---------------------------------------------------------------- ----------\nmaximum PGA memory for optimal 0\nestimated PGA memory for one-pass 0\nmaximum PGA memory for one-pass 0\n14 rows selected.\nSQL> create table abc(id int,name varchar2(10)) tablespace users;\nTable created.\nSQL> begin\n2 for i in 1.100000\n3 loop\n4 insert into abc values(i,''dgdggd'');\n5 commit;\n6 end loop;\n7 end;\n8 /\nloop\n*\nERROR at line 3:\nORA-06550: line 3, column 1:\nPLS-00103: Encountered the symbol \"LOOP\" when expecting one of the following:\n* & - + / at mod rem .. ||\nSQL> ed\nWrote file afiedt.buf\n1 begin\n2 for i in 1..100000\n3 loop\n4 insert into abc values(i,''dgdggd'');\n5 commit;\n6 end loop;\n7* end;\nSQL> /\nPL/SQL procedure successfully completed.\nSQL> create index idx4 abc (id) nologging;\ncreate index idx4 abc (id) nologging\n*\nERROR at line 1:\nORA-00969: missing ON keyword\nSQL> create index idx4 on abc (id) nologging;\nIndex created.\nSQL> set autotrace on explain\nSP2-0613: Unable to verify PLAN_TABLE format or existence\nSP2-0611: Error enabling EXPLAIN report\nSQL> @ C:\\oracle\\ora90\\rdbms\\admin\\utlxplan.sql\nTable created.\nSQL> set autotrace on explain\nSQL> select * from abc where id=101;\nID NAME\n---------- ----------\n101 dgdggd\nExecution Plan\n----------------------------------------------------------\n0 SELECT STATEMENT Optimizer=CHOOSE\n1 0 TABLE ACCESS (BY INDEX ROWID) OF ''ABC''\n2 1 INDEX (RANGE SCAN) OF ''IDX4'' (NON-UNIQUE)\nSQL> alter table abc move tablespace examples;\nalter table abc move tablespace examples\n*\nERROR at line 1:\nORA-00959: tablespace ''EXAMPLES'' does not exist\nSQL> alter table abc move tablespace example;\nTable altered.\nSQL> select * from abc where id=101;\nselect * from abc where id=101\n*\nERROR at line 1:\nORA-01502: index ''SYS.IDX4'' or partition of such index is in unusable state\nSQL> alter index idx4 rebuild online;\nIndex altered.\nSQL> select * from abc where id=101;\nID NAME\n---------- ----------\n101 dgdggd\nExecution Plan\n----------------------------------------------------------\n0 SELECT STATEMENT Optimizer=CHOOSE\n1 0 TABLE ACCESS (BY INDEX ROWID) OF ''ABC''\n2 1 INDEX (RANGE SCAN) OF ''IDX4'' (NON-UNIQUE)\nSQL>\nSQL>\nSQL> set autotrace off;\nSQL> select height,blocks,lf_rows,lf_blks,del_lf_rows,lf_rows from index_stats w\nhere name=''IDX4'';\nno rows selected\nSQL> show user;\nUSER is \"SYS\"\nSQL> analyze index idx4 validate structure;\nIndex analyzed.\nSQL> select height,blocks,lf_rows,lf_blks,del_lf_rows,lf_rows from index_stats w\nhere name=''IDX4'';\nHEIGHT BLOCKS LF_ROWS LF_BLKS DEL_LF_ROWS LF_ROWS\n---------- ---------- ---------- ---------- ----------- ----------\n3 641 100000 456 0 100000\nSQL> delete from abc where id>40000 and id commit;\nCommit complete.\nSQL> analyze index idx4 validate structure;\nIndex analyzed.\nSQL> select height,blocks,lf_rows,lf_blks,del_lf_rows,lf_rows from index_stats w\nhere name=''IDX4'';\nHEIGHT BLOCKS LF_ROWS LF_BLKS DEL_LF_ROWS LF_ROWS\n---------- ---------- ---------- ---------- ----------- ----------\n3 641 100000 456 40000 100000\nSQL>"}]'::jsonb,
