SELECT gen_random_uuid(), 'page', 8, 'oracleasm', 'oracleasm', 'ASM creation on kernel version 2.6.18-238.el5 #1 SMP Tue Jan 4 15:41:11 EST 2011 x86_64 x86_64 x86_64 GNU/Linux [root@rac-1 ~]# /etc/init.d/oracleasm configure Configuring the Oracle ASM library driver. This will configure the on-boot properties of the Oracle ASM library driver. The following…', '{"type":"none"}'::jsonb, '[{"type":"html","html":"<p><strong><br>\nASM creation on kernel version  2.6.18-238.el5 #1 SMP Tue Jan 4 15:41:11 EST 2011 x86_64 x86_64 x86_64 GNU/Linux</strong></p>"},{"type":"quote","text":"[root@rac-1 ~]# /etc/init.d/oracleasm configure\nConfiguring the Oracle ASM library driver.\nThis will configure the on-boot properties of the Oracle ASM library\ndriver. The following questions will determine whether the driver is\nloaded on boot and what permissions it will have. The current values\nwill be shown in brackets (‘[]’). Hitting without typing an\nanswer will keep that current value. Ctrl-C will abort.\nDefault user to own the driver interface [oracle]:\nDefault group to own the driver interface [oinstall]:\nStart Oracle ASM library driver on boot (y/n) [y]:\nScan for Oracle ASM disks on boot (y/n) [y]:\nWriting Oracle ASM library driver configuration: done\nInitializing the Oracle ASMLib driver: [ OK ]\nScanning the system for Oracle ASMLib disks: [ OK ]\n[root@rac-1 ~]# fdisk -l\nDisk /dev/sda: 1000.2 GB, 1000204886016 bytes\n255 heads, 63 sectors/track, 121601 cylinders\nUnits = cylinders of 16065 * 512 = 8225280 bytes\nDevice Boot Start End Blocks Id System\n/dev/sda1 * 1 13 104391 83 Linux\n/dev/sda2 14 3929 31455270 8e Linux LVM\n/dev/sda3 3930 121601 945200340 5 Extended\n/dev/sda5 3930 24410 164513601 8e Linux LVM\n/dev/sda6 24411 28146 30009388+ 8e Linux LVM\n/dev/sda7 28147 28769 5004216 83 Linux\nDisk /dev/dm-0: 21.4 GB, 21474836480 bytes\n255 heads, 63 sectors/track, 2610 cylinders\nUnits = cylinders of 16065 * 512 = 8225280 bytes\nDisk /dev/dm-0 doesn’t contain a valid partition table\nDisk /dev/dm-1: 5368 MB, 5368709120 bytes\n255 heads, 63 sectors/track, 652 cylinders\nUnits = cylinders of 16065 * 512 = 8225280 bytes\nDisk /dev/dm-1 doesn’t contain a valid partition table\nDisk /dev/dm-2: 5368 MB, 5368709120 bytes\n255 heads, 63 sectors/track, 652 cylinders\nUnits = cylinders of 16065 * 512 = 8225280 bytes\nDisk /dev/dm-2 doesn’t contain a valid partition table\nDisk /dev/dm-3: 21.4 GB, 21474836480 bytes\n255 heads, 63 sectors/track, 2610 cylinders\nUnits = cylinders of 16065 * 512 = 8225280 bytes\nDisk /dev/dm-3 doesn’t contain a valid partition table\nDisk /dev/dm-4: 2147 MB, 2147483648 bytes\n255 heads, 63 sectors/track, 261 cylinders\nUnits = cylinders of 16065 * 512 = 8225280 bytes\nDisk /dev/dm-4 doesn’t contain a valid partition table\n[root@rac-1 ~]# oracleasm createdisk VOL1 /dev/sda7\nWriting disk header: done\nInstantiating disk: done\n[root@rac-1 ~]#"},{"type":"quote","text":"The oracleasm package contains only the kernel driver, which is included in the Oracle Unbreakable Enterprise kernel and does not need to be installed. If I remember correctly, OEL 5.6 installed the UEK kernel by default.\nThe oracleasm-support and oracelasmlib packages however are still required. If you do not have paid access to the ULN network you can install the oracleasm-support rpm from Oracle’s public yum repository (http://public-yum.oracle.com/). Using yum is easy and will also resolve package dependency issues.\nTo install oracleasmlib you can try:\nrpm -ivh ‘http://download.oracle.com/otn_software/asmlib/oracleasmlib-2.0.4-1.el5.x86_64.rpm&#8217;\nIf newer version of ASMlib comes you need check that also according to the kernel version"}]'::jsonb,
  NULL, 'csayantan', '{}'::text[], '{}'::text[], '{"title":"oracleasm","description":"ASM creation on kernel version 2.6.18-238.el5 #1 SMP Tue Jan 4 15:41:11 EST 2011 x86_64 x86_64 x86_64 GNU/Linux [root@rac-1 ~]# /etc/init.d/oracleasm…","canonical":"https://cadentic.dev/11gr2-rac-installation/oracleasm","noindex":false}'::jsonb, 'draft', NULL,
  '2010-04-25T18:32:34Z'::timestamptz, 'wordpress', '111', now(), now()
