SELECT gen_random_uuid(), 'page', 2, 'hot-cloning-in-oracle-ebs-r12', 'HOT CLONING IN ORACLE EBS R12', '1. Rman hotbackup of source instance. run { backup database plus archivelog; } 2. set oracle_sid=<source instance> 3. modify pfile of target instance. db_name= db_unique_name=…', '{"type":"none"}'::jsonb, '[{"type":"paragraph","text":"1. Rman hotbackup of source instance."},{"type":"quote","text":"run {\nbackup database plus archivelog;\n}"},{"type":"paragraph","text":"2. set oracle_sid=<source instance>"},{"type":"paragraph","text":"3. modify pfile of target instance."},{"type":"quote","text":"db_name=\ndb_unique_name=\n*.control_files=''/d04/oraclone/db/apps_st/data/cntrl01.dbf'',''/d04/oraclone/db/apps_st/data/cntrl02.dbf'',''/d04/oraclone/db/apps_st/data/cntrl03.dbf''"},{"type":"paragraph","text":"4.rman resotoration of controlfile in target instance."},{"type":"quote","text":"Startup nomount pfile=;\nrman target / nocatalog\nRMAN>\nRMAN> restore controlfile from '''';\nRMAN> catalog start with '''';"},{"type":"paragraph","text":"5. set ‘newname’ of each datafile and restoration of the database is needed to perform on ‘mount’ state. ie. After catalogging backuppiece, issue “restore database” command. If you need to restore datafiles\nto a location different to the one recorded in controlfile, use SET NEWNAME command as below:"},{"type":"html","html":"<p><code><br>\nrman target / &lt;&lt; EOF<br>\nrun {<br>\nset newname for datafile 1 to &#39;/d04/oraclone/db/apps_st/data/system01.dbf&#39;;<br>\nset newname for datafile 2 to &#39;/d04/oraclone/db/apps_st/data/system02.dbf&#39;;<br>\nset newname for datafile 3 to &#39;/d04/oraclone/db/apps_st/data/system03.dbf&#39;;<br>\nset newname for datafile 4 to &#39;/d04/oraclone/db/apps_st/data/system04.dbf&#39;;<br>\nset newname for datafile 5 to &#39;/d04/oraclone/db/apps_st/data/system05.dbf&#39;;<br>\nset newname for datafile 6 to &#39;/d04/oraclone/db/apps_st/data/ctxd01.dbf&#39;;<br>\nset newname for datafile 7 to &#39;/d04/oraclone/db/apps_st/data/owad01.dbf&#39;;<br>\nset newname for datafile 8 to &#39;/d04/oraclone/db/apps_st/data/a_queue02.dbf&#39;;<br>\nset newname for datafile 9 to &#39;/d04/oraclone/db/apps_st/data/odm.dbf&#39;;<br>\nset newname for datafile 10 to &#39;/d04/oraclone/db/apps_st/data/olap.dbf&#39;;<br>\nset newname for datafile 11 to &#39;/d04/oraclone/db/apps_st/data/sysaux01.dbf&#39;;<br>\nset newname for datafile 12 to &#39;/d04/oraclone/db/apps_st/data/apps_ts_tools01.dbf&#39;;<br>\nset newname for datafile 13 to &#39;/d04/oraclone/db/apps_st/data/system12.dbf&#39;;<br>\nset newname for datafile 14 to &#39;/d04/oraclone/db/apps_st/data/a_txn_data04.dbf&#39;;<br>\nset newname for datafile 15 to &#39;/d04/oraclone/db/apps_st/data/a_txn_ind06.dbf&#39;;<br>\nset newname for datafile 16 to &#39;/d04/oraclone/db/apps_st/data/a_ref03.dbf&#39;;<br>\nset newname for datafile 17 to &#39;/d04/oraclone/db/apps_st/data/a_int02.dbf&#39;;<br>\nset newname for datafile 18 to &#39;/d04/oraclone/db/apps_st/data/sysaux02.dbf&#39;;<br>\nset newname for datafile 19 to &#39;/d04/oraclone/db/apps_st/data/olap01.dbf&#39;;<br>\nset newname for datafile 20 to &#39;/d04/oraclone/db/apps_st/data/undo2.dbf&#39;;<br>\nset newname for datafile 21 to &#39;/d04/oraclone/db/apps_st/data/sysaux03.dbf&#39;;<br>\nset newname for datafile 22 to &#39;/d04/oraclone/db/apps_st/data/a_txn_data05.dbf&#39;;<br>\nset newname for datafile 23 to &#39;/d04/oraclone/db/apps_st/data/a_txn_data06.dbf&#39;;<br>\nset newname for datafile 24 to &#39;/d04/oraclone/db/apps_st/data/a_txn_ind07.dbf&#39;;<br>\nset newname for datafile 25 to &#39;/d04/oraclone/db/apps_st/data/mallcom.dbf&#39;;<br>\nset newname for datafile 26 to &#39;/d04/oraclone/db/apps_st/data/xxmallcom.dbf&#39;;<br>\nset newname for datafile 27 to &#39;/d04/oraclone/db/apps_st/data/sysaux04.dbf&#39;;<br>\nset newname for datafile 28 to &#39;/d04/oraclone/db/apps_st/data/a_nolog02.dbf&#39;;<br>\nset newname for datafile 29 to &#39;/d04/oraclone/db/apps_st/data/odm01.dbf&#39;;<br>\nset newname for datafile 30 to &#39;/d04/oraclone/db/apps_st/data/olap02.dbf&#39;;<br>\nset newname for datafile 31 to &#39;/d04/oraclone/db/apps_st/data/a_txn_ind08.dbf&#39;;<br>\nset newname for datafile 32 to &#39;/d04/oraclone/db/apps_st/data/a_txn_ind09.dbf&#39;;<br>\nset newname for datafile 33 to &#39;/d04/oraclone/db/apps_st/data/a_media02.dbf&#39;;<br>\nset newname for datafile 288 to &#39;/d04/oraclone/db/apps_st/data/system10.dbf&#39;;<br>\nset newname for datafile 295 to &#39;/d04/oraclone/db/apps_st/data/system06.dbf&#39;;<br>\nset newname for datafile 314 to &#39;/d04/oraclone/db/apps_st/data/portal01.dbf&#39;;<br>\nset newname for datafile 351 to  &#39;/d04/oraclone/db/apps_st/data/system07.dbf&#39;;<br>\nset newname for datafile 352 to &#39;/d04/oraclone/db/apps_st/data/system09.dbf&#39;;<br>\nset newname for datafile 353 to &#39;/d04/oraclone/db/apps_st/data/system08.dbf&#39;;<br>\nset newname for datafile 354 to &#39;/d04/oraclone/db/apps_st/data/system11.dbf&#39;;<br>\nset newname for datafile 379 to &#39;/d04/oraclone/db/apps_st/data/undo01.dbf&#39;;<br>\nset newname for datafile 392 to &#39;/d04/oraclone/db/apps_st/data/a_txn_data01.dbf&#39;;<br>\nset newname for datafile 393 to &#39;/d04/oraclone/db/apps_st/data/a_txn_ind01.dbf&#39;;<br>\n## set newname for datafile 393 to &#39;/d04/oraclone/db/apps_st/data/a_txn_ind01.dbf&#39;;<br>\nset newname for datafile 394 to &#39;/d04/oraclone/db/apps_st/data/a_ref01.dbf&#39;;<br>\nset newname for datafile 395 to &#39;/d04/oraclone/db/apps_st/data/a_int01.dbf&#39;;<br>\nset newname for datafile 396 to &#39;/d04/oraclone/db/apps_st/data/a_summ01.dbf&#39;;<br>\nset newname for datafile 397 to &#39;/d04/oraclone/db/apps_st/data/a_nolog01.dbf&#39;;<br>\nset newname for datafile 398 to &#39;/d04/oraclone/db/apps_st/data/a_archive01.dbf&#39;;<br>\nset newname for datafile 399 to &#39;/d04/oraclone/db/apps_st/data/a_queue01.dbf&#39;;<br>\nset newname for datafile 400 to &#39;/d04/oraclone/db/apps_st/data/a_media01.dbf&#39;;<br>\nset newname for datafile 401 to &#39;/d04/oraclone/db/apps_st/data/a_txn_data02.dbf&#39;;<br>\nset newname for datafile 402 to &#39;/d04/oraclone/db/apps_st/data/a_txn_data03.dbf&#39;;<br>\nset newname for datafile 403 to &#39;/d04/oraclone/db/apps_st/data/a_txn_ind02.dbf&#39;;<br>\nset newname for datafile 404 to &#39;/d04/oraclone/db/apps_st/data/a_txn_ind03.dbf&#39;;<br>\nset newname for datafile 405 to &#39;/d04/oraclone/db/apps_st/data/a_txn_ind04.dbf&#39;;<br>\nset newname for datafile 406 to &#39;/d04/oraclone/db/apps_st/data/a_txn_ind05.dbf&#39;;<br>\nset newname for datafile 407 to &#39;/d04/oraclone/db/apps_st/data/a_ref02.dbf&#39;;<br>\nrestore database;<br>\nswitch datafile all;<br>\nrecover database;<br>\n}<br>\nEOF</code></p>"},{"type":"paragraph","text":"6.rename redolog files."},{"type":"paragraph","text":"7.recover database until cancel using backup controlfile;"},{"type":"paragraph","text":"alter database rename file ''/d01/oramall/db/apps_st/data/log01a.dbf'' to ''/d01/oraclone/db/apps_st/data/log01a.dbf'';\nalter database rename file ''/d01/oramall/db/apps_st/data/log01b.dbf'' to ''/d04/oraclone/db/apps_st/data/log01b.dbf'';\nalter database rename file ''/d01/oraclone/db/apps_st/data/log01a.dbf'' to ''/d04/oraclone/db/apps_st/data/log01a.dbf'';\nalter database rename file ''/d01/oramall/db/apps_st/data/log02a.dbf'' to ''/d04/oraclone/db/apps_st/data/log02a.dbf'';\netc.\nalter database open resetlogs;"},{"type":"paragraph","text":"8.alter database open resetlogs."},{"type":"paragraph","text":"9.shutdown the instance. and startup in mount state using pfile.drop each tempfile;"},{"type":"html","html":"<p><code><br>\nselect * from v$tempfile ;<br>\nalter database tempfile 1 drop ;<br>\n</code></p>"},{"type":"paragraph","text":"10.Issue ‘nid’ to change the SID."},{"type":"html","html":"<p><code><br>\n nid TARGET=/ as sysdba DBNAME=VINTEST<br>\n</code></p>"},{"type":"paragraph","text":"11. perform hot backup of apps instance.And run the rapidclone."},{"type":"paragraph","text":"RELATED ERROR ENCOUNTERED :"},{"type":"quote","text":"Running DBNEWID returns:\nNID-00111: Oracle error reported from target database while executing\nbegin dbms_backup_restore.nidprocessdf(:fno, :istemp, :skipped, :idchged, :d); end;\nORA-01116: error in opening database file /oracleP/oradat/BO73/temp01.dbf\nORA-27037: unable to obtain file status\nHPUX-ia64 Error: 2: No such file or directory\nAdditional information: 3\nORA-06512: at “SYS.X$DBMS_BACKUP_RESTORE”, line 6694\nORA-06512: at line 1"},{"type":"quote","text":"SQL> Select distinct(FHDBI) ,count(*) from x$kcvfh group by fhdbi;\nSelect distinct(FHDBI) ,count(*) from x$kcvfh group by fhdbi\n*\nERROR at line 1:\nORA-01507: database not mounted\nSQL> alter database mount;\nalter database mount\n*\nERROR at line 1:\nORA-00205: error in identifying control file, check alert log for more info"}]'::jsonb,
  NULL, 'csayantan', '{}'::text[], '{}'::text[], '{"title":"HOT CLONING IN ORACLE EBS R12","description":"1. Rman hotbackup of source instance. run { backup database plus archivelog; } 2. set oracle_sid=<source instance> 3. modify pfile of target instance…","canonical":"https://cadentic.dev/oracle-apps-r12/hot-cloning-in-oracle-ebs-r12","noindex":false}'::jsonb, 'draft', NULL,
