SELECT gen_random_uuid(), 'page', 3, 'custom-top-creatio-in-oracle-ebs-r12', 'CUSTOM TOP CREATION IN Oracle EBS R12', '1) Make the directory structure for your custom application files. cd $APPL_TOP mkdir XXERP mkdir XXERP/12.0.0 mkdir XXERP/12.0.0/admin mkdir XXERP/12.0.0/admin/sql mkdir XXERP/12.0.0/admin/odf mkdir XXERP/12.0.0/sql mkdir XXERP/12.0.0/bin mkdir XXERP/12.0.0/reports mkdir XXERP/12.0.0/reports/US…', '{"type":"none"}'::jsonb, '[{"type":"quote","text":"1) Make the directory structure for your custom application files.\ncd $APPL_TOP\nmkdir XXERP\nmkdir XXERP/12.0.0\nmkdir XXERP/12.0.0/admin\nmkdir XXERP/12.0.0/admin/sql\nmkdir XXERP/12.0.0/admin/odf\nmkdir XXERP/12.0.0/sql\nmkdir XXERP/12.0.0/bin\nmkdir XXERP/12.0.0/reports\nmkdir XXERP/12.0.0/reports/US\nmkdir XXERP/12.0.0/forms\nmkdir XXERP/12.0.0/forms/US\nmkdir XXERP/12.0.0/lib\nmkdir XXERP/12.0.0/out\nmkdir XXERP/12.0.0/log"},{"type":"quote","text":"2) Add the custom module into the environment\ncd $APPL_TOP\necho \"XXERP_TOP=/d01/oracle/PROD/apps/apps_st/appl/XXERP/12.0.0\" >\ncustomPROD_linux7.env\necho \"export XXERP_TOP \" >> customPROD_linux7.env"},{"type":"quote","text":"3) RUN AUTOCONFIG ON APPS TIER"},{"type":"quote","text":"4) BOUNCE THE APPLICATION TIER"},{"type":"html","html":"<p><strong><br>\nNOTE:-<br>\nYou need a custom schema and datafile to have all your custom objects in this schema</strong></p>"},{"type":"quote","text":"If i create new custom_top i use below grants;\nCREATE USER XX\nIDENTIFIED BY XX\nDEFAULT TABLESPACE XX\nTEMPORARY TABLESPACE TEMP\nPROFILE DEFAULT\nACCOUNT UNLOCK;\nGRANT CONNECT TO XX;\nALTER USER XX DEFAULT ROLE ALL;\nGRANT CREATE VIEW TO XX;\nGRANT CREATE TABLE TO XX;\nGRANT CREATE SESSION TO XX;\nGRANT CREATE SYNONYM TO XX;\nGRANT CREATE TRIGGER TO XX;\nGRANT CREATE SEQUENCE TO XX;\nGRANT CREATE PROCEDURE TO XX;\nGRANT CREATE PUBLIC SYNONYM TO XX;\nALTER USER XX QUOTA UNLIMITED ON XX;\nALTER USER XX QUOTA UNLIMITED ON XX_INDEX;"}]'::jsonb,
  NULL, 'csayantan', '{}'::text[], '{}'::text[], '{"title":"CUSTOM TOP CREATION IN Oracle EBS R12","description":"1) Make the directory structure for your custom application files. cd $APPL_TOP mkdir XXERP mkdir XXERP/12.0.0 mkdir XXERP/12.0.0/admin mkdir…","canonical":"https://cadentic.dev/oracle-apps-r12/custom-top-creatio-in-oracle-ebs-r12","noindex":false}'::jsonb, 'draft', NULL,
