SELECT gen_random_uuid(), 'page', 4, 'applying-patch-to-fix-bug-5230186-txkapps1012-reports-user-exits-failing', 'APPLYING PATCH TO FIX Bug.5230186: TXK:APPS1012: REPORTS USER EXITS FAILING', 'IT was reported from our technical team that some reports are not running.And the “Active Users” screen is showing that its completed with error.So we made an SR: [demoap@demo ~]$ $INST_TOP/ora/10.1.2/bin/appsrwrun.sh userid=apps_usr/apps_pwd report=$ONT_TOP/reports/US/WILPACKSLIP.rdf…', '{"type":"none"}'::jsonb, '[{"type":"html","html":"<p>IT was reported from our technical team that <strong>some</strong> reports are not running.And the “Active Users” screen is showing that its completed with error.So we made an SR:</p>"},{"type":"quote","text":"[demoap@demo ~]$ $INST_TOP/ora/10.1.2/bin/appsrwrun.sh userid=apps_usr/apps_pwd report=$ONT_TOP/reports/US/WILPACKSLIP.rdf desformat=$FND_TOP/reports/HPL desname=WIPPACKSLIP.pdf destype=file batch=yes traceopts=traceall tracefile=./ddr5.trc P_DELV_ID=8022"},{"type":"quote","text":"LOG :\nReport: /t01/demoap/apps/apps_st/appl/ont/12.0.0/reports/US/WILPACKSLIP.rdf\nLogged onto server:\nUsername:\n*** Starting up the JVM ***\nJVM CLASSPATH variable is:\n/t01/demoap/apps/tech_st/10.1.2/reports/jlib/rwbuilder.jar:/t01/demoap/apps/tech_st/10.1.2/reports/jlib/rwrun.jar:/t01/demoap/apps/tech_st/10.1.2/jlib/zrclient.jar:/t01/demoap/apps/tech_st/10.1.2/j2ee/home/oc4j.jar:/t01/demoap/apps/tech_st/10.1.2/j2ee/home/lib/ojsp.jar\n*** JVM started successfully ***\n[2010/6/23 0:37:56:889] Debug 50103 (EnvironmentUtility:getEnvironment): CE_TOP=/t01/demoap/apps/apps_st/appl/ce/12.0.0\n[2010/6/23 0:37:56:889] Debug 50103 (EnvironmentUtility:getEnvironment): APPLREP=reports\n[2010/6/23 0:37:56:889] Debug 50103 (EnvironmentUtility:getEnvironment): NLS_SORT=BINARY\n[2010/6/23 0:37:56:889] Debug 50103 (EnvironmentUtility:getEnvironment): AHL_TOP=/t01/demoap/apps/apps_st/appl/ahl/12.0.0\n[2010/6/23 0:37:56:889] Debug 50103 (EnvironmentUtility:getEnvironment