SELECT gen_random_uuid(), 'page', 6, '161-2', 'Concurrent Manager encountered an error while running SQL*Plus for your concurrent request', 'Symptoms : while running specific report some times you may face this problem. +—————————————————————————+ Purchasing: Version : 12.0.0 Copyright (c) 1979, 1999, Oracle Corporation. All rights reserved. POXPOPDOI module: Import Standard Purchase Orders +—————————————————————————+ Current system…', '{"type":"none"}'::jsonb, '[{"type":"paragraph","text":"Symptoms :"},{"type":"paragraph","text":"while running specific report some times you may face this problem."},{"type":"quote","text":"+---------------------------------------------------------------------------+\nPurchasing: Version : 12.0.0\nCopyright (c) 1979, 1999, Oracle Corporation. All rights reserved.\nPOXPOPDOI module: Import Standard Purchase Orders\n+---------------------------------------------------------------------------+\nCurrent system time is 19-JUL-2010 13:29:26\n+---------------------------------------------------------------------------+\n+-----------------------------\n| Starting concurrent program execution...\n+-----------------------------\nArguments\n------------\nSTANDARD\nN\nINCOMPLETE\n------------\n+---------------------------------------------------------------------------+\nStart of log messages from FND_FILE\n+---------------------------------------------------------------------------+\n+---------------------------------------------------------------------------+\nEnd of log messages from FND_FILE\n+---------------------------------------------------------------------------+\nConcurrent Manager encountered an error while running SQL*Plus for your concurrent request 492644.\nReview your concurrent request log and/or report output file for more detailed information.\n+---------------------------------------------------------------------------+\nExecuting request completion options...\nFinished executing request completion options.\n+---------------------------------------------------------------------------+\nConcurrent request completed\nCurrent system time is 19-JUL-2010 13:29:27\n+---------------------------------------------------------------------------+\nStep 1)check for invalid object.\nStep 2)if there is some objects then compile then.\nStep 4)check for temp directory permission in my case it was /usr/tmp\nif the issue is still there.\nStep 5)check for spaces in /usr/tmp if u notice that disk space is low\nStep 6)check for unwanted log and remove them like cups log.\nif the issue is still exist\nStep 7)enable concurrent debug on user level from define -> profile Step 8)issue tkprof on $ORACLE_HOME/admin/udump/xxxxx.trc folder.\nStep 9)change the profile option again to default one.check for ora-erros errors etc."}]'::jsonb,
  NULL, 'csayantan', '{}'::text[], '{}'::text[], '{"title":"Concurrent Manager encountered an error while running SQL*Plus for your concurrent request","description":"Symptoms : while running specific report some times you may face this problem. +—————————————————————————+ Purchasing: Version : 12.0.0 Copyright (c) 1979…","canonical":"https://cadentic.dev/oracle-apps-r12/161-2","noindex":false}'::jsonb, 'draft', NULL,
