SELECT gen_random_uuid(), 'page', 8, 'when-attempting-to-generate-a-distribution-in-an-invoice-with-project-the-following-error-occurs-app-sqlap-97734-the-system-cannot-generate-distributions-for-line-1-because-token2', 'When attempting to generate a distribution in an invoice with project, the following error occurs, APP-SQLAP-97734: The system cannot generate distributions for line 1 because &TOKEN2', 'Cause: This is explained in the following bug: Bug 8320268 – INVOICE WITH PROJECT CODE-APP-SQLAP-97734:THE SYSTEM CANNOT GENERATE DISTRIBUTION After applying the patch you may found invalid object. Jai_ap_tds_generation_pkg Does Not Compile [ID 870615.1] In aputilsb.pls, the procedure pa_flexbuild…', '{"type":"none"}'::jsonb, '[{"type":"html","html":"<p>Cause:<br>\nThis is explained in the following bug:<br>\n<strong><br>\nBug 8320268 – INVOICE WITH PROJECT CODE-APP-SQLAP-97734:THE SYSTEM CANNOT GENERATE DISTRIBUTION</strong></p>"},{"type":"quote","text":"After applying the patch you may found invalid object.\nJai_ap_tds_generation_pkg Does Not Compile [ID 870615.1]"},{"type":"paragraph","text":"In aputilsb.pls, the procedure pa_flexbuild has calls to pa_acc_gen_wf_pkg.ap_er_generate_account and pa_acc_gen_wf_pkg.ap_inv_generate_account. The out parameter for error reporting in this procedure is p_debug_info. But it wasn’t being assigned the error output from the procedures called."},{"type":"html","html":"<p><strong>This issue has been fixed in the file apiindib.pls 120.59.12000000.17<br>\n</strong></p>"},{"type":"quote","text":"capturing the log:\nPlease provide the fnd log once again using following steps for my analysis:\nPlease follow the below steps and provide me the log in excel:\na) Using the System Administrator Responsibility, navigate to Profile > System\nCheck the User checkbox and fill in your user name\nIn the Profile field enter: FND: Debug%\nClick Find\nAt the User level, set the following profile option values:\nFND: Debug Log Enabled Yes\nFND: Debug Log Level Statement\nFND: Debug Log Module %\nSave your changes\nb)select max(log_sequence)\nfrom fnd_log_messages;\n---- Please note the above query result which has to be given in step (d).\nc) Now reproduce the issue.\nd) Get the Debug Messages:\nPlease upload the result of the below query:"},{"type":"quote","text":"select log_sequence, module, message_text from fnd_log_messages\nwhere log_sequence > &max_log_sequence_from_step_b\norder by log_sequence;"}]'::jsonb,
  NULL, 'csayantan', '{}'::text[], '{}'::text[], '{"title":"When attempting to generate a distribution in an invoice with project, the following error occurs, APP-SQLAP-97734: The system cannot generate distributions for line 1 because &TOKEN2","description":"Cause: This is explained in the following bug: Bug 8320268 – INVOICE WITH PROJECT CODE-APP-SQLAP-97734:THE SYSTEM CANNOT GENERATE DISTRIBUTION After applying…","canonical":"https://cadentic.dev/oracle-apps-r12/when-attempting-to-generate-a-distribution-in-an-invoice-with-project-the-following-error-occurs-app-sqlap-97734-the-system-cannot-generate-distributions-for-line-1-because-token2","noindex":false}'::jsonb, 'draft', NULL,
