SELECT gen_random_uuid(), 'page', 11, 'fnd-tables-for-login-details', 'FND tables for login details', 'How to find user logged in Oracle Applications and and I would like restrict some user login during weekends to oracle applications. How Logged to Forms select distinct fu.user_name User_Name,fr.RESPONSIBILITY_KEY Responsibility from fnd_user fu, fnd_responsibility fr, icx_sessions ic where…', '{"type":"none"}'::jsonb, '[{"type":"quote","text":"How to find user logged in Oracle Applications and and I would like restrict some user login during weekends to oracle applications.\nHow Logged to Forms\nselect distinct fu.user_name User_Name,fr.RESPONSIBILITY_KEY Responsibility from fnd_user fu,\nfnd_responsibility fr, icx_sessions ic\nwhere fu.user_id = ic.user_id AND\nfr.responsibility_id = ic.responsibility_id AND\nic.disabled_flag=’N’ AND\nic.responsibility_id is not null AND\nic.last_connect like sysdate;"},{"type":"quote","text":"There are three primary tables which are involved in using the system profile ‘Sign-On:Audit Level’:\n1) FND_LOGINS\n2) FND_LOGIN_RESPONSIBILITIES\n3) FND_LOGIN_RESP_FORMS\n– When the profile is set to “User”, the only table that gets updated is the table FND_LOGINS and only one record per user session\n– When the profile is set to “Responsibility”, both FND_LOGINS and FND_LOGIN_RESPONSIBILITIES will be updated:\na) FND_LOGINS gets only one record per user session\nb) FND_LOGIN_RESPONSIBILITIES will be updated with one record for each responsibility selected during the session\n– When the profile is set to “Form” all three tables are involved:\na) FND_LOGINS gets only one record per user session\nb) FND_LOGIN_RESPONSIBILITIES will be updated with one record for each responsibility selected during the session\nc) FND_LOGIN_RESP_FORMS will be updated with one record for each form selected during the session\nIn terms of performance, the data capture has negligible overhead."}]'::jsonb,
  NULL, 'csayantan', '{}'::text[], '{}'::text[], '{"title":"FND tables for login details","description":"How to find user logged in Oracle Applications and and I would like restrict some user login during weekends to oracle applications. How Logged to Forms…","canonical":"https://cadentic.dev/oracle-apps-r12/fnd-tables-for-login-details","noindex":false}'::jsonb, 'draft', NULL,
  '2010-07-23T05:22:00Z'::timestamptz, 'wordpress', '193', now(), now()
WHERE NOT EXISTS (
  SELECT 1 FROM cms_pages WHERE kind = 'page' AND slug = 'fnd-tables-for-login-details'
