SELECT gen_random_uuid(), 'page', 8, 'grant-to-objectstable-of-all_objectsdba_objects-within-a-cursor', 'Grant to objects/table of all_objects/dba_objects within a cursor', 'declare cursor cur is select table_name from all_tables where Owner = ‘HR’; var all_Tables.Table_Name%type; begin open cur; loop fetch cur into var; exit when cur%notfound; execute immediate ‘grant all on hr.’ || var || ‘ to SCOTT’; end loop; close cur; exception when others then if (cur%isopen)…', '{"type":"none"}'::jsonb, '[{"type":"quote","text":"declare\ncursor cur is\nselect table_name\nfrom all_tables\nwhere Owner = ''HR'';\nvar all_Tables.Table_Name%type;\nbegin\nopen cur;\nloop\nfetch cur into var;\nexit when cur%notfound;\nexecute immediate ''grant all on hr.'' || var || '' to SCOTT'';\nend loop;\nclose cur;\nexception\nwhen others then\nif (cur%isopen) then\nclose cur;\nend if;\nend;\n/"},{"type":"html","html":"<p><strong>Try this code as a scott user</strong></p>"},{"type":"quote","text":"select * from hr.employees;\nupdate hr.employees set last_name= ''OConnel'' where last_name=''OConnel'';\ncommit;"}]'::jsonb,
  NULL, 'csayantan', '{}'::text[], '{}'::text[], '{"title":"Grant to objects/table of all_objects/dba_objects within a cursor","description":"declare cursor cur is select table_name from all_tables where Owner = ‘HR’; var all_Tables.Table_Name%type; begin open cur; loop fetch cur into var; exit when…","canonical":"https://cadentic.dev/oca-ocp-10g-class-notes-and-practice/grant-to-objectstable-of-all_objectsdba_objects-within-a-cursor","noindex":false}'::jsonb, 'draft', NULL,
