SELECT gen_random_uuid(), 'page', 13, 'fnd_log_messages_n4-and-apps_tx_ts_idx-growing-unexpectedly', 'FND_LOG_MESSAGES_N4 and apps_tx_ts_idx growing unexpectedly', 'FND_LOG_MESSAGES_N4 and apps_tx_ts_idx growing unexpectedly There are some index is usually stored in this tablespace.if the tablespace grows up the index will also grow up accordingly.the extreme growth of fnd_log_messages may affect the size of the listed indexes : FND_LOG_MESSAGES_N4…', '{"type":"none"}'::jsonb, '[{"type":"html","html":"<p><strong><br>\nFND_LOG_MESSAGES_N4 and apps_tx_ts_idx growing unexpectedly<br>\n</strong></p>"},{"type":"quote","text":"There are some index is usually stored in this tablespace.if the tablespace grows up the index will also grow up accordingly.the extreme growth of fnd_log_messages may affect the size of the listed indexes :\nFND_LOG_MESSAGES_N4\nDR$FND_LOBS_CTX$I\nFND_LOG_MESSAGES_N8\nFND_LOG_MESSAGES_N7\nCST_RCV_ACQ_COST_DETAILS_N1\nDR$FND_LOBS_CTX$X\nCST_RCV_ACQ_COST_DETAILS_U1\nFND_LOG_MESSAGES_N5\nAX_RULE_LINES_N2\nyou need to investigate a lot to know which table is responsible for this growth.the main reason which is very normal in all the cases is FND debug is set at site level.so the work around should be like:\n1)purging obsolete system alert and log messages.\ncheck again the size of apps_tx_ts_idx tablespace if it is still not reduced\n2)truncate table applsys.FND_LOG_MESSAGES;\nit is recommended by oracle also.\nit will reduce the tablespace size.moreover you can do:\n3)index rebuild with online\nbefore step 3 you must put off fnd debug log from profile option from site-level as well as the user level.If you do not put off this option it will create another problem."}]'::jsonb,
  NULL, 'csayantan', '{}'::text[], '{}'::text[], '{"title":"FND_LOG_MESSAGES_N4 and apps_tx_ts_idx growing unexpectedly","description":"FND_LOG_MESSAGES_N4 and apps_tx_ts_idx growing unexpectedly There are some index is usually stored in this tablespace.if the tablespace grows up the index…","canonical":"https://cadentic.dev/oracle-apps-r12/fnd_log_messages_n4-and-apps_tx_ts_idx-growing-unexpectedly","noindex":false}'::jsonb, 'draft', NULL,
  '2010-08-07T04:24:11Z'::timestamptz, 'wordpress', '216', now(), now()
