SELECT gen_random_uuid(), 'page', 7, 'finding-the-size-of-a-tablespace', 'finding the size of a tablespace', 'SELECT F.TABLESPACE_NAME pTablespaceName ,TO_CHAR ((T.TOTAL_SPACE – F.FREE_SPACE),’999,999′) pUsedSpace ,TO_CHAR (F.FREE_SPACE, ‘999,999’) pFreeSpace ,TO_CHAR (T.TOTAL_SPACE, ‘999,999’) pTotalSpace ,TO_CHAR ((ROUND ((F.FREE_SPACE/T.TOTAL_SPACE)*100)),’999′)||’ %’ pPercentFree FROM ( SELECT…', '{"type":"none"}'::jsonb, '[{"type":"quote","text":"SELECT F.TABLESPACE_NAME pTablespaceName\n,TO_CHAR ((T.TOTAL_SPACE - F.FREE_SPACE),''999,999'') pUsedSpace\n,TO_CHAR (F.FREE_SPACE, ''999,999'') pFreeSpace\n,TO_CHAR (T.TOTAL_SPACE, ''999,999'') pTotalSpace\n,TO_CHAR ((ROUND ((F.FREE_SPACE/T.TOTAL_SPACE)*100)),''999'')||'' %'' pPercentFree\nFROM\n( SELECT TABLESPACE_NAME,\nROUND (SUM (BLOCKS*(SELECT VALUE/1024\nFROM V$PARAMETER\nWHERE NAME = ''db_block_size'')/1024)) FREE_SPACE\nFROM DBA_FREE_SPACE\nGROUP BY TABLESPACE_NAME ) F,\n( SELECT TABLESPACE_NAME,\nROUND (SUM (BYTES/1048576)) TOTAL_SPACE\nFROM DBA_DATA_FILES\nGROUP BY TABLESPACE_NAME ) T\nWHERE F.TABLESPACE_NAME = T.TABLESPACE_NAME;"},{"type":"html","html":"<p><strong><br>\nI used this script on 10.2.0.0.It worked.<br>\n</strong></p>"}]'::jsonb,
  NULL, 'csayantan', '{}'::text[], '{}'::text[], '{"title":"finding the size of a tablespace","description":"SELECT F.TABLESPACE_NAME pTablespaceName ,TO_CHAR ((T.TOTAL_SPACE – F.FREE_SPACE),’999,999′) pUsedSpace ,TO_CHAR (F.FREE_SPACE, ‘999,999’) pFreeSpace ,TO_CHAR…","canonical":"https://cadentic.dev/oca-ocp-10g-class-notes-and-practice/finding-the-size-of-a-tablespace","noindex":false}'::jsonb, 'draft', NULL,
