SELECT gen_random_uuid(), 'page', 16, 'relink-issue-ebs-r12-dbconsole-reports-failed-to-connect-to-database-instance-ora-12537-tnsconnection-closed-dbd-error-ociserverattach', 'relink issue EBS R12 DBCONSOLE reports “Failed to connect to database instance: ORA-12537: TNS:connection closed (DBD ERROR: OCIServerAttach)', '. Regenerate the .so files by giving command For DBConsole only: cd /sysman/lib/ make -f ins_sysman.mk install . Regenerate the .so files by giving command Set ORACLE_HOME and ORACLE_SID export ORACLE_HOME= export ORACLE_SID= 5. Relink all the components in the Oracle home relink all 6. Set…', '{"type":"none"}'::jsonb, '[{"type":"quote","text":". Regenerate the .so files by giving command\nFor DBConsole only:\ncd /sysman/lib/\nmake -f ins_sysman.mk install\n. Regenerate the .so files by giving command\nSet ORACLE_HOME and ORACLE_SID\nexport ORACLE_HOME=\nexport ORACLE_SID=\n5. Relink all the components in the Oracle home\nrelink all\n6. Set LD_LIBRARY_PATH\nexport LD_LIBRARY_PATH=$ORACLE_HOME/lib\n7. Set the LIBPATH\nexport LIBPATH=$LD_LIBRARY_PATH:$ORACLE_HOME/lib32:$ORACLE_HOME/lib:$ORACLE_HOME/perl/lib\n8. Disable kernel runtime linking\nexport LDR_CNTRL=NOKRTL\ntry emca start dbconsole"},{"type":"html","html":"<p><strong>After this i found</strong></p>"},{"type":"quote","text":"500 Internal Server Error\noracle.apps.fnd.cache.CacheException at oracle.apps.fnd.cache.AppsCache.get(AppsCache.java:228) at oracle.apps.fnd.profiles.Profiles.getProfileOption(Profiles.java:1485) at oracle.apps.fnd.profiles.Profiles.getProfile(Profiles.java:354) at oracle.apps.fnd.profiles.ExtendedProfileStore.getSpecificProfileFromDB(ExtendedProfileStore.java:211) at oracle.apps.fnd.profiles.ExtendedProfileStore.getSpecificProfile(ExtendedProfileStore.java:171) at oracle.apps.fnd.profiles.ExtendedProfileStore.getProfile(ExtendedProfileStore.java:148) at oracle.apps.fnd.common.logging.DebugEventManager.configureUsingDatabaseValues(DebugEventManager.java:1259) at oracle.ap