SELECT gen_random_uuid(), 'page', 20, 'workflow-mailer-not-working-properly', 'workflow mailer not working properly', 'nested exception is: class javax.mail.SendFailedException: 554 5.7.1 : Relay access denied [Aug 12, 2010 1:28:37 PM GMT+05:30]:1281599917186:-1:-1:prod.com:127.0.0.1:-1:-1:1:20420:SYSADMIN(0):-1:Thread[outboundThreadGroup1,5,outboundThreadGroup]:127.0.0.1:50291:1281599917176:16:ERROR:[SVC-GSM-WFMLR…', '{"type":"none"}'::jsonb, '[{"type":"quote","text":"nested exception is:\nclass javax.mail.SendFailedException: 554 5.7.1 : Relay access denied\n[Aug 12, 2010 1:28:37 PM GMT+05:30]:1281599917186:-1:-1:prod.com:127.0.0.1:-1:-1:1:20420:SYSADMIN(0):-1:Thread[outboundThreadGroup1,5,outboundThreadGroup]:127.0.0.1:50291:1281599917176:16:ERROR:[SVC-GSM-WFMLRSVC-127699-10006 : oracle.apps.fnd.wf.mailer.SMTPMessageHandler.sendMessages(String)]:SendFailedException -> [[SYSADMIN ]] javax.mail.SendFailedException: Invalid Addresses;\nnested exception is:\nclass javax.mail.SendFailedException: 554 5.7.1 : Relay access denied\n[Aug 12, 2010 1:28:37 PM GMT+05:30]:1281599917589:-1:-1:prod.com:127.0.0.1:-1:-1:1:20420:SYSADMIN(0):-1:Thread[outboundThreadGroup1,5,outboundThreadGroup]:127.0.0.1:50291:1281599917176:16:ERROR:[SVC-GSM-WFMLRSVC-127699-10006 : oracle.apps.fnd.wf.mailer.SMTPMessageHandler.sendMessages(String)]:None of the recipients for notification {50504} is valid. Notification will not be sent. Check that the recipients"},{"type":"html","html":"<p><strong>to investigating this issue we need</strong></p>"},{"type":"quote","text":"select * from wf_notifications order by begin_date;\nselect target_node\nfrom fnd_concurrent_queues where concurrent_queue_name like ''WFMLRSVC%'';\nSELECT b.component_name,\nc.parameter_name,\na.parameter_value\nFROM fnd_svc_comp_param_vals a,\nfnd_svc_components b,\nfnd_svc_comp_params_b c\nWHERE b.component_id = a.component_id\nAND b.component_type = c.component_type\nAND c.parameter_id = a.parameter_id\nAND c.encrypted_flag = ''N''\nAND b.component_name like ''%Mailer%''\nAND c.parameter_name in (''OUTBOUND_SERVER'', ''REPLYTO'')\nORDER BY c.parameter_name;"},{"type":"paragraph","text":"then you need to navigate through:"},{"type":"quote","text":"first you need to create the employee from hrms module.\nwipl hrms -> people -> maintenance and enter.\nthen from system administrator responsibility -> you must add the email center to that employee from sysadmin -> security -> users -> define"},{"type":"quote","text":"then you must system administrator -> workflow -> workflow mailer -> edit -> put mail server ip address -> set reply to."},{"type":"quote","text":"you need to end with the update query to wf_notifications just changing the mail status."},{"type":"quote","text":"Please see (Note: 753845.1 – How to Perform a Meaningful SMTP Telnet Test to Troubleshoot Java Mailer Issues), the same error is reported in this doc.\nNote: 1054215.1 – How to Check if the Workflow Mailer is Running\nNote: 415516.1 – How to Check Whether Notification Mailer is Working or Not\nNote: 831982.1 – 11i/R12 – A guide for troubleshoting Workflow Notification Emails – Inbound and Outbound\nNote: 1012344.7 – Notifications Not Being Sent In Workflow\nNote: 560472.1 – Workflow Mailers Not Sending Notifications"}]'::jsonb,
  NULL, 'csayantan', '{}'::text[], '{}'::text[], '{"title":"workflow mailer not working properly","description":"nested exception is: class javax.mail.SendFailedException: 554 5.7.1 : Relay access denied [Aug 12, 2010 1:28:37 PM…","canonical":"https://cadentic.dev/oracle-apps-r12/workflow-mailer-not-working-properly","noindex":false}'::jsonb, 'draft', NULL,
  '2010-08-12T09:12:17Z'::timestamptz, 'wordpress', '244', now(), now()
