SELECT gen_random_uuid(), 'page', 21, 'investigating-output-post-processor', 'investigating Output post processor', 'SELECT fcpp.concurrent_request_id req_id, fcp.node_name, fcp.logfile_name FROM fnd_conc_pp_actions fcpp, fnd_concurrent_processes fcp WHERE fcpp.processor_id = fcp.concurrent_process_id AND fcpp.action_type = 6 AND fcpp.concurrent_request_id = &&request_id –set serveroutput on declare cursor c is…', '{"type":"none"}'::jsonb, '[{"type":"quote","text":"SELECT fcpp.concurrent_request_id req_id, fcp.node_name, fcp.logfile_name\nFROM fnd_conc_pp_actions fcpp, fnd_concurrent_processes fcp\nWHERE fcpp.processor_id = fcp.concurrent_process_id\nAND fcpp.action_type = 6\nAND fcpp.concurrent_request_id = &&request_id\n–set serveroutput on\ndeclare\ncursor c is\nselect concurrent_process_id\nfrom fnd_concurrent_processes fcp, fnd_concurrent_queues fcq, fnd_cp_services fcs\nwhere fcs.service_handle = ‘FNDOPP’ and fcs.service_id = fcq.manager_type\nand fcq.concurrent_queue_id = fcp.concurrent_queue_id\nand fcp.process_status_code = ‘A’;\nbegin\nfor crec in c loop\ndbms_output.put_line(‘Setting debug on for process id: ‘ || crec.concurrent_process_id);\nfnd_cp_opp_ipc.send_command(crec.concurrent_process_id, ‘sqlplus’,\n‘oracle.apps.fnd.cp.opp.OPPSetDebugCommand’, ‘1’);\nend loop;\nend;\nexec c;\nSELECT xcpt.property_name, xcp.xdo_cfg_name,\nDECODE (TO_CHAR (xcv.config_level), ’10’, ‘Site’,’30’, ‘DataSource’,’50’, ‘Template’,\n‘???’) “LEVEL”,\nDECODE (TO_CHAR (xcv.config_level), ’10’, ”,\n’30’, xd.application_short_name || ‘|’ || xd.data_source_code,\n’50’, xt.application_short_name || ‘|’ || xt.template_code,\n‘???’) “CONTEXT_SHORT”,\nDECODE (TO_CHAR (xcv.config_level), ’10’, ”,\n’30’, (SELECT fat1.application_name || ‘|’ || xdt.data_source_name\nFROM xdo_ds_definitions_tl xdt, fnd_application fa1, fnd_application_tl fat1\nWHERE fa1.application_id = fat1.application_id AND fat1.LANGUAGE = ‘US’\nAND xd.application_short_name = fa1.application_short_name\nAND xd.application_short_name = xdt.application_short_name\nAND xd.data_source_code = xdt.data_source_code AND xdt.LANGUAGE = ‘US’),\n’50’, (SELECT fat2.application_name || ‘|’ || xtt.template_name\nFROM xdo_templates_tl xtt, fnd_application fa2, fnd_application_tl fat2\nWHERE fa2.application_id = fat2.application_id AND fat2.LANGUAGE = ‘US’\nAND xt.application_short_name = fa2.application_short_name\nAND xt.application_short_name = xtt.application_short_name\nAND xtt.template_code = xt.template_code AND xtt.LANGUAGE = ‘US’),\n‘???’ ) “CONTEXT_DETAIL”, xcv.VALUE\nFROM xdo_config_properties_b xcp, xdo_config_properties_tl xcpt,\nxdo_config_values xcv, xdo_ds_definitions_b xd, xdo_templates_b xt\nWHERE xcp.property_code = xcpt.property_code AND xcpt.LANGUAGE = ‘US’\nAND xcv.property_code = xcp.property_code\nAND xd.application_short_name(+) = xcv.application_short_name\nAND xd.data_source_code(+) = xcv.data_source_code\nAND xt.application_short_name(+) = xcv.application_short_name\nAND xt.template_code(+) = xcv.template_code\nORDER BY xcv.config_level, xcp.CATEGORY, xcp.sort_order;"}]'::jsonb,
  NULL, 'csayantan', '{}'::text[], '{}'::text[], '{"title":"investigating Output post processor","description":"SELECT fcpp.concurrent_request_id req_id, fcp.node_name, fcp.logfile_name FROM fnd_conc_pp_actions fcpp, fnd_concurrent_processes fcp WHERE fcpp.processor_id…","canonical":"https://cadentic.dev/oracle-apps-r12/investigating-output-post-processor","noindex":false}'::jsonb, 'draft', NULL,
  '2010-08-13T10:13:06Z'::timestamptz, 'wordpress', '256', now(), now()
