SELECT gen_random_uuid(), 'page', 10, 'putting-database-in-single-user-mode-to-reduce-space-issue-in-the-partition-of-ebs-r12alter-system-quiesce-restricted', 'putting database in single user mode to reduce space issue in the partition of EBS R12:ALTER SYSTEM QUIESCE RESTRICTED', 'ALTER SYSTEM QUIESCE RESTRICTED The ALTER SYSTEM QUIESCE RESTRICTED statement may wait a long time for active sessions to become inactive. You can determine the sessions that are blocking the quiesce operation by querying the V$BLOCKING_QUIESCE view. This view returns only a single column: SID…', '{"type":"none"}'::jsonb, '[{"type":"html","html":"<p><strong><br>\nALTER SYSTEM QUIESCE RESTRICTED</strong></p>"},{"type":"quote","text":"The ALTER SYSTEM QUIESCE RESTRICTED statement may wait a long time for active sessions to become inactive. You can determine the sessions that are blocking the quiesce operation by querying the V$BLOCKING_QUIESCE view. This view returns only a single column: SID (Session ID). You can join it with V$SESSION to get more information about the session, as shown in the following example:"},{"type":"quote","text":"ALTER SYSTEM QUIESCE RESTRICTED"},{"type":"html","html":"<p><a href=\"http://www.comp.dit.ie/btierney/oracle11gdoc/server.111/b28310/start004.htm\">http://www.comp.dit.ie/btierney/oracle11gdoc/server.111/b28310/start004.htm</a></p>"},{"type":"quote","text":"select bl.sid, user, osuser, type, program\nfrom v$blocking_quiesce bl, v$session se\nwhere bl.sid = se.sid;"}]'::jsonb,
  NULL, 'csayantan', '{}'::text[], '{}'::text[], '{"title":"putting database in single user mode to reduce space issue in the partition of EBS R12:ALTER SYSTEM QUIESCE RESTRICTED","description":"ALTER SYSTEM QUIESCE RESTRICTED The ALTER SYSTEM QUIESCE RESTRICTED statement may wait a long time for active sessions to become inactive. You can determine…","canonical":"https://cadentic.dev/oca-ocp-10g-class-notes-and-practice/putting-database-in-single-user-mode-to-reduce-space-issue-in-the-partition-of-ebs-r12alter-system-quiesce-restricted","noindex":false}'::jsonb, 'draft', NULL,
