SELECT gen_random_uuid(), 'page', 1, 'restoring-the-system-to-normal-operation', 'Restoring the System to Normal Operation after QUIESCE', 'The following statement restores the database to normal operation: ALTER SYSTEM UNQUIESCE; All non-DBA activity is allowed to proceed. In an Oracle Real Application Clusters environment, this statement is not required to be issued from the same session, or even the same instance, as that which…', '{"type":"none"}'::jsonb, '[{"type":"quote","text":"The following statement restores the database to normal operation:\nALTER SYSTEM UNQUIESCE;\nAll non-DBA activity is allowed to proceed. In an Oracle Real Application Clusters environment, this statement is not required to be issued from the same session, or even the same instance, as that which quiesced the database. If the session issuing the ALTER SYSTEM UNQUIESCE statement terminates abnormally, then the Oracle Database server ensures that the unquiesce operation completes."}]'::jsonb,
