SELECT gen_random_uuid(), 'page', 2, 'script-to-install-own-sql-script', 'script to install own sql script', 'V1.0.0 #!/usr/bin/env bash echo “Enter the user name who will be the owner of this script \n” read $user for sqlfile in $(ls -l *.sql |awk ‘{print $9}’); do # echo $sqlfilei echo “sqlplus / as sysdba @$(pwd)/$sqlfile” > ${sqlfile%.*}.sh install -c ${sqlfile%.*}.sh /usr/local/bin done chown -R…', '{"type":"none"}'::jsonb, '[{"type":"html","html":"<p><strong>V1.0.0</strong></p>"},{"type":"quote","text":"#!/usr/bin/env bash\necho “Enter the user name who will be the owner of this script \\n”\nread $user\nfor sqlfile in $(ls -l *.sql |awk ‘{print $9}’); do\n# echo $sqlfilei\necho “sqlplus / as sysdba @$(pwd)/$sqlfile” > ${sqlfile%.*}.sh\ninstall -c ${sqlfile%.*}.sh /usr/local/bin\ndone\nchown -R $user:dba .\nchmod -R 755 ."},{"type":"html","html":"<p><strong>Perl format but it has some fault</strong></p>"},{"type":"quote","text":"#!/usr/bin/perl\n##use Fcntl; #The Module\n$dirtoget=”.”;\nopendir(IMD, $dirtoget) || die(“Cannot open directory”);\n@thefiles= readdir(IMD);\n#closedir(IMD);\nchomp($pwd = `pwd`); # running unix command “free”\nprint “$pwd \\n” ;\nopen(TEXT,”>>newtext.txt”);\n#printf TEXT “@thefiles”;\nforeach $f (@thefiles)\n{\nunless ( ($f eq “.”) || ($f eq “..”) || ($f eq “creating-file.pl”))\n{\n$filename=”@” . $pwd . “/” . $f;\nprint “$filename \\n”;\nopen(SCRIPTS,”>>$f”);\nprintf SCRIPTS “sqlplus / as sysdba $filename \\n”;\nclose(SCRIPTS);\n# system(“install -c /usr/local/bin”);\n}\n}\nclose (TEXT);\nclosedir(IMD);"},{"type":"html","html":"<p><strong>v1.0.1</strong></p>"},{"type":"quote","text":"#!/usr/bin/env bash\necho “Enter the user name who will be the owner of this script \\n”\nread $user\n##############################################################################\n# THIS PART OF THE SCRIPT IS GENERATING SOME SHELL SCRIPT\n# WHICH WILL CALL SOME SQL SCRIPT\n##############################################################################\nfor sqlfile in $(ls -l *.sql |awk ‘{print $9}’); do\n# echo $sqlfilei\necho “sqlplus / as sysdba @$(pwd)/$sqlfile” > ${sqlfile%.*}.sh\ninstall -c ${sqlfile%.*}.sh /usr/local/bin\ndone\nchown -R $user:dba .\nchmod -R 755 .\n##############################################################################\n# THIS PART OF THE SCRIPT IS MAKING SHELL SCRIPTS\n# TO BE CALLED FROM ANY USERS’ HOME\n##############################################################################\nfor shfile in $(ls -l *.sh |awk ‘{print $9}’); do\ninstall -c $shfile /usr/local/bin\ndone\nrm -rf /usr/local/bin/$0\nexit 0"}]'::jsonb,
  NULL, 'csayantan', '{}'::text[], '{}'::text[], '{"title":"script to install own sql script","description":"V1.0.0 #!/usr/bin/env bash echo “Enter the user name who will be the owner of this script \\n” read $user for sqlfile in $(ls -l *.sql |awk ‘{print $9}’); do #…","canonical":"https://cadentic.dev/linux-rhel5-basics/script-to-install-own-sql-script","noindex":false}'::jsonb, 'draft', NULL,
  '2010-08-22T06:35:04Z'::timestamptz, 'wordpress', '269', now(), now()
