SELECT gen_random_uuid(), 'page', 3, 'liblibdb-so-2-no-such-file-or-directory-apache-error', 'lib/libdb.so.2 : No such file or directory Apache Error', 'ln -s /usr/lib/libgdbm.so.2.0.0 /usr/lib/libdb.so.2 For JRE 1.5_20 grep sun_plugin_ver $CONTEXT_FILE 1.5.0_20 Download the same version from http://java.sun.com/javase/downloads/5u20/jre install jre-1_5_0_20-linux-i586.rpm: # cd /usr/lib/jvm/ # ./jre-1_5_0_20-linux-i586.bin # cd…', '{"type":"none"}'::jsonb, '[{"type":"quote","text":"ln -s /usr/lib/libgdbm.so.2.0.0 /usr/lib/libdb.so.2\nFor JRE 1.5_20\ngrep sun_plugin_ver $CONTEXT_FILE\n1.5.0_20\nDownload the same version from http://java.sun.com/javase/downloads/5u20/jre\ninstall jre-1_5_0_20-linux-i586.rpm:\n# cd /usr/lib/jvm/\n# ./jre-1_5_0_20-linux-i586.bin\n# cd /usr/lib/mozilla/plugins\n# ln -s /usr/lib/jvm/jre1.5.0_20/plugin/i386/ns7/libjavaplugin_oji.so\n# linux32 bash\n# firefox\nI could open forms once I used linux32 bash to open a 32-bit firefox. Apparently, 64-bit Sun Java Plugin only works with 1.6.0_15 and higher."}]'::jsonb,
