SELECT gen_random_uuid(), 'page', 1, 'progress-ber', 'progress ber', 'Progress Ber script v.1 copy() { # src dst [width] srcsize=$(stat -c %s $1) || return $? dstsize=0 width=${3:-25} mega=$(( 1024 * 1024 )) start=$(date +%s) cat $1 | ( while [[ dstsize -lt srcsize ]] do dd bs=512 count=2048 2>/dev/null || return $? (( dstsize += $mega )) [[ dstsize -gt srcsize ]] &&', '{"type":"none"}'::jsonb, '[{"type":"html","html":"<p><strong>Progress Ber script v.1</strong></p>"},{"type":"quote","text":"copy() { # src dst [width]\nsrcsize=$(stat -c %s $1) || return $?\ndstsize=0\nwidth=${3:-25}\nmega=$(( 1024 * 1024 ))\nstart=$(date +%s)\ncat $1 | (\nwhile [[ dstsize -lt srcsize ]]\ndo\ndd bs=512 count=2048 2>/dev/null || return $?\n(( dstsize += $mega ))\n[[ dstsize -gt srcsize ]] && dstsize=$srcsize\nprintf “\\r%-20s Progress: ” 1>&2\n# print percentage\npercent=$(( 100 * $dstsize / $srcsize ))\nprintf “%3d%% [” $percent 1>&2\n# print progress bar\nbar=$(( $width * $dstsize / $srcsize ))\nfor i in $(seq 1 $bar); do printf “=” 1>&2; done\nfor i in $(seq $bar $(( $width-1 ))); do printf ” ” 1>&2; done\nprintf “]” 1>&2\ndone\necho 1>&2\n) | cat >$2\n}\ncopy FILE_1 FILE_2\nrm -rf FILE_2"},{"type":"html","html":"<p><strong>progress ber V 1.0.1</strong></p>"},{"type":"quote","text":"copy() {\n# initial values\nprogress=0\nend=27\nwidth=${3:-25}\nwhile [[ progress -lt end ]]\ndo\nprintf “\\r%-20s Progress: ” 1>&2\n# print percentage\npercent=$(( 100 * $progress / $end ))\nprintf “%3d%% [” $percent 1>&2\n# print progress bar\nbar=$(( $width * $progress / $end ))\nfor i in $(seq 1 $bar); do printf “=” 1>&2; done\nfor i in $(seq $bar $(( $width-1 ))); do printf ” ” 1>&2; done\nprintf “]” 1>&2\nsleep 0.1\nprogress=$progress+1\ndone\necho 1>&2\n}"},{"type":"quote","text":"#!/usr/local/bin/perli\n# use strict;\nuse warnings;\nuse File::stat;\n# Total from which percentage will be calculated\n$cnt =16;\n#my $cnt=stat(“creating-file.pl”)->size;\n#print “$cnt”;\n$|=1;\nfor(my $i=0;$isize;\n# Calculate Percentage\nmy $percent = ($i/$cnt)*100;\n# Print Progress\nfor(my $k=0;$k>>>>>>>>>———100% Complete———<<<<<<<<<<\\n\";"}]'::jsonb,
  NULL, 'csayantan', '{}'::text[], '{}'::text[], '{"title":"progress ber","description":"Progress Ber script v.1 copy() { # src dst [width] srcsize=$(stat -c %s $1) || return $? dstsize=0 width=${3:-25} mega=$(( 1024 * 1024 )) start=$(date +%s)…","canonical":"https://cadentic.dev/linux-rhel5-basics/progress-ber","noindex":false}'::jsonb, 'draft', NULL,
