SELECT gen_random_uuid(), 'page', 6, 'changing-gid-or-global_name', 'changing GID or GLOBAL_NAME', 'CHANGING GLOBAL_NAME [oracle@rac-1 ~]$ sqlplus / as sysdba SQL*Plus: Release 11.2.0.1.0 Production on Mon Sep 13 05:47:26 2010 Copyright (c) 1982, 2009, Oracle. All rights reserved. Connected to an idle instance. SQL> startup ORACLE instance started. Total System Global Area 2505338880 bytes Fixed…', '{"type":"none"}'::jsonb, '[{"type":"html","html":"<p><strong>CHANGING GLOBAL_NAME</strong></p>"},{"type":"quote","text":"[oracle@rac-1 ~]$ sqlplus / as sysdba\nSQL*Plus: Release 11.2.0.1.0 Production on Mon Sep 13 05:47:26 2010\nCopyright (c) 1982, 2009, Oracle. All rights reserved.\nConnected to an idle instance.\nSQL> startup\nORACLE instance started.\nTotal System Global Area 2505338880 bytes\nFixed Size 2215944 bytes\nVariable Size 1392513016 bytes\nDatabase Buffers 1090519040 bytes\nRedo Buffers 20090880 bytes\nDatabase mounted.\nDatabase opened.\nSQL> global\nSP2-0042: unknown command “global” – rest of line ignored.\nSQL> show parameter global\nNAME TYPE VALUE\n———————————— ———– ——————————\nglobal_context_pool_size string\nglobal_names boolean FALSE\nglobal_txn_processes integer 1\nSQL> SELECT * FROM GLOBAL_NAME;\nGLOBAL_NAME\n——————————————————————————–\nORCL.RAC-1.SAYANTAN-CHAKRABORTY.DE\nSQL> alter database rename global_name to ‘ORCL.SAYANTAN-CHAKRABORTY.DE’;\nalter database rename global_name to ‘ORCL.SAYANTAN-CHAKRABORTY.DE’\n*\nERROR at line 1:\nORA-01729: database link name expected\nSQL> alter database rename global_name to ORCL.SAYANTAN-CHAKRABORTY.DE;\nalter database rename global_name to ORCL.SAYANTAN-CHAKRABORTY.DE\n*\nERROR at line 1:\nORA-00933: SQL command not properly ended\nSQL> alter database rename global_name to “ORCL.SAYANTAN-CHAKRABORTY.DE”;\nDatabase altered.\nSQL> SELECT * FROM GLOBAL_NAME\n2 ;\nGLOBAL_NAME\n——————————————————————————–\nORCL.SAYANTAN-CHAKRABORTY.DE\nSQL>"}]'::jsonb,
