SELECT gen_random_uuid(), 'page', 4, 'ora-01775-looping-chain-of-synonyms', 'ORA-01775: looping chain of synonyms', 'Creating a public synonym that refers to another non-existent object of the same name will do it: create public synonym never_before_seen_name for other_schema.never_before_seen_name; Synonym created. select * from never_before_seen_name; select * from never_before_seen_name * ERROR at line 1…', '{"type":"none"}'::jsonb, '[{"type":"quote","text":"Creating a public synonym that refers to another non-existent object of the same name will do it:\ncreate public synonym never_before_seen_name for other_schema.never_before_seen_name;\nSynonym created.\nselect * from never_before_seen_name;\nselect * from never_before_seen_name\n*\nERROR at line 1:\nORA-01775: looping chain of synonyms\nThis is because your query reference to never_before_seen_name\n–> does not find such an object in your own schema, and so resolves to the public synonym never_before_seen_name\n—-> which then attempts to resolve never_before_seen_name from the perspective of other_schema\n——> which does not find such an object in that schema, so it then resolves back to the public synonym\nhence the ‘looping chain of synonyms’."},{"type":"html","html":"<p><strong>For oracle Apps  FND_COMMON_LOOKUPS </strong></p>"},{"type":"quote","text":"Also, FND_COMMON_LOOKUPS is an Oracle Apps view in the APPS schema, with the following SQL:\nselect flt.application_id\n,flt.lookup_type\n,flv.lookup_code\n,flv.meaning\n,flv.description\n,flv.enabled_flag\n,flv.start_date_active\n,flv.end_date_active\n,flv.created_by\n,flv.creation_date\n,flv.last_update_date\n,flv.last_updated_by\n,flv.last_update_login\n,flv.attribute_category\n,flv.attribute1\n,flv.attribute2\n,flv.attribute3\n,flv.attribute4\n,flv.attribute5\n,flv.attribute6\n,flv.attribute7\n,flv.attribute8\n,flv.attribute9\n,flv.attribute10\n,flv.attribute11\n,flv.attribute12\n,flv.attribute13\n,flv.attribute14\n,flv.attribute15\nfrom FND_lookup_types flt\n,FND_lookup_values flv\nwhere flv.Lookup_type = flt.Lookup_type\nand flv.Security_group_id = flt.Security_group_id\nand flv.View_application_id = flt.View_application_id\nand flv.Language = userenv ( ‘LANG’ )\nand flv.View_application_id = 3\nand flv.Security_group_id = fnd_global.lookup_security_group ( flv.Lookup_type, flv.View_application_id );"}]'::jsonb,
  NULL, 'csayantan', '{}'::text[], '{}'::text[], '{"title":"ORA-01775: looping chain of synonyms","description":"Creating a public synonym that refers to another non-existent object of the same name will do it: create public synonym never_before_seen_name for…","canonical":"https://cadentic.dev/oca-ocp-10g-class-notes-and-practice/ora-01775-looping-chain-of-synonyms","noindex":false}'::jsonb, 'draft', NULL,
  '2010-09-15T05:41:57Z'::timestamptz, 'wordpress', '314', now(), now()
