SELECT gen_random_uuid(), 'page', 6, 'user_recyclebin-and-recyclebin-in-10g-11g', 'user_recyclebin and recyclebin in 10g & 11g', 'SQL> select * from user_recyclebin; no rows selected SQL> desc user_recyclebin; Name Null? Type —————————————– ——– —————————- OBJECT_NAME NOT NULL VARCHAR2(30) ORIGINAL_NAME VARCHAR2(32) OPERATION VARCHAR2(9) TYPE VARCHAR2(25) TS_NAME VARCHAR2(30) CREATETIME VARCHAR2(19) DROPTIME VARCHAR2(19)…', '{"type":"none"}'::jsonb, '[{"type":"quote","text":"SQL> select * from user_recyclebin;\nno rows selected\nSQL> desc user_recyclebin;\nName Null? Type\n—————————————– ——– —————————-\nOBJECT_NAME NOT NULL VARCHAR2(30)\nORIGINAL_NAME VARCHAR2(32)\nOPERATION VARCHAR2(9)\nTYPE VARCHAR2(25)\nTS_NAME VARCHAR2(30)\nCREATETIME VARCHAR2(19)\nDROPTIME VARCHAR2(19)\nDROPSCN NUMBER\nPARTITION_NAME VARCHAR2(32)\nCAN_UNDROP VARCHAR2(3)\nCAN_PURGE VARCHAR2(3)\nRELATED NOT NULL NUMBER\nBASE_OBJECT NOT NULL NUMBER\nPURGE_OBJECT NOT NULL NUMBER\nSPACE NUMBER\nSQL> show parameter recyclebin\nNAME TYPE VALUE\n———————————— ———– ——————————\nrecyclebin string on\nSQL>"}]'::jsonb,
  NULL, 'csayantan', '{}'::text[], '{}'::text[], '{"title":"user_recyclebin and recyclebin in 10g & 11g","description":"SQL> select * from user_recyclebin; no rows selected SQL> desc user_recyclebin; Name Null? Type —————————————– ——– —————————- OBJECT_NAME NOT NULL…","canonical":"https://cadentic.dev/oca-ocp-10g-class-notes-and-practice/user_recyclebin-and-recyclebin-in-10g-11g","noindex":false}'::jsonb, 'draft', NULL,
