SELECT gen_random_uuid(), 'page', 15, 'the-rman-hot-backup-script-rman_backup-sh', 'The RMAN hot backup script rman_backup.sh:', 'RMAN Hot backup—unix script ******************************************* The RMAN hot backup script rman_backup.sh: # !/bin/bash # Declare your environment variables export ORACLE_SID= (put your SID here) export ORACLE_BASE= (put your ORACLE BASE here) export ORACLE_HOME= (put your ORACLE_HOME…', '{"type":"none"}'::jsonb, '[{"type":"quote","text":"RMAN Hot backup—unix script\n*******************************************\nThe RMAN hot backup script rman_backup.sh:\n# !/bin/bash\n# Declare your environment variables\nexport ORACLE_SID= (put your SID here)\nexport ORACLE_BASE= (put your ORACLE BASE here)\nexport ORACLE_HOME= (put your ORACLE_HOME here)\nexport PATH=$PATH:${ORACLE_HOME}/bin\n# Start the rman commands\nrman target=/ << EOF\nCONFIGURE CONTROLFILE AUTOBACKUP ON;\nCONFIGURE CONTROLFILE AUTOBACKUP FORMAT FOR DEVICE TYPE DISK TO ‘/(put backup directory here)/autobackup_control_file%F’;\nCONFIGURE RETENTION POLICY TO RECOVERY WINDOW OF 2 DAYS;\nrun {\nALLOCATE CHANNEL RMAN_BACK_CH01 TYPE DISK;\nCROSSCHECK BACKUP;\nBACKUP AS COMPRESSED BACKUPSET DATABASE FORMAT ‘/(put backup directory here)/databasefiles_%d_%u_%s_%T’;\nsql ‘ALTER SYSTEM ARCHIVE LOG CURRENT’;\nBACKUP AS COMPRESSED BACKUPSET ARCHIVELOG ALL FORMAT ‘/(put backup directory here)/archivelogs_%d_%u_%s_%T’ DELETE INPUT;\nBACKUP AS COMPRESSED BACKUPSET CURRENT CONTROLFILE FORMAT ‘/(put backup directory here)/controlfile_%d_%u_%s_%T’;\nCROSSCHECK BACKUP;\nDELETE NOPROMPT OBSOLETE;\nDELETE NOPROMPT EXPIRED BACKUP;\nRELEASE CHANNEL RMAN_BACK_CH01;\n}\nEXIT;\nEOF\n#"}]'::jsonb,
  NULL, 'csayantan', '{}'::text[], '{}'::text[], '{"title":"The RMAN hot backup script rman_backup.sh:","description":"RMAN Hot backup—unix script ******************************************* The RMAN hot backup script rman_backup.sh: # !/bin/bash # Declare your environment…","canonical":"https://cadentic.dev/oca-ocp-10g-class-notes-and-practice/the-rman-hot-backup-script-rman_backup-sh","noindex":false}'::jsonb, 'draft', NULL,
