SELECT gen_random_uuid(), 'page', 16, 'deletion-of-archivelog', 'deletion of archivelog', 'From sqlplus: connect / as sysdba set serveroutput on; spool C:\scripts\output_del_logs.txt declare CURSOR cur IS SELECT a.name FROM v$asm_alias a, v$asm_file b where a.group_number = b.group_number and b.creation_date < sysdate-7 and a.file_number = b.file_number and b.type=''ARCHIVELOG'' and…', '{"type":"none"}'::jsonb, '[{"type":"quote","text":"From sqlplus:\nconnect / as sysdba\nset serveroutput on;\nspool C:\\scripts\\output_del_logs.txt\ndeclare CURSOR cur IS\nSELECT a.name\nFROM v$asm_alias a, v$asm_file b\nwhere a.group_number = b.group_number\nand b.creation_date < sysdate-7\nand a.file_number = b.file_number\nand b.type=''ARCHIVELOG''\nand a.name like ''%.arc''\norder by a.name;\nsqlstr VARCHAR2(250);\nBEGIN\nFOR cur_rec IN cur\nLOOP\nsqlstr := ''alter diskgroup ASM_BACKUP drop file ''''+ASM_BACKUP/DB1/'' || cur_rec.name || '''''''';\nDBMS_OUTPUT.PUT_LINE(sqlstr);\nEXECUTE IMMEDIATE sqlstr;\nEND LOOP;\nEND;\n/\nspool off;\nexit\n2)\nFrom RMAN\nrun {\ncrosscheck archivelog all;\ndelete expired archivelog all;\n}"}]'::jsonb,
  NULL, 'csayantan', '{}'::text[], '{}'::text[], '{"title":"deletion of archivelog","description":"From sqlplus: connect / as sysdba set serveroutput on; spool C:\\scripts\\output_del_logs.txt declare CURSOR cur IS SELECT a.name FROM v$asm_alias a, v$asm_file…","canonical":"https://cadentic.dev/oca-ocp-10g-class-notes-and-practice/deletion-of-archivelog","noindex":false}'::jsonb, 'draft', NULL,
  '2010-09-25T18:02:29Z'::timestamptz, 'wordpress', '325', now(), now()
