SELECT gen_random_uuid(), 'page', 1, 'asm-creation-problem-initializing-the-oracle-asmlib-driver-failed', 'ASM creation problem Initializing the Oracle ASMLib driver: failed', 'Loading module “oracleasm”: failed To investigate such error : one must check /var/log/oracleasm Creating /dev/oracleasm mount point: /dev/oracleasm Loading module “oracleasm”: failed Unable to load module “oracleasm” Loading module “oracleasm”: failed Unable to load module “oracleasm” Loading…', '{"type":"none"}'::jsonb, '[{"type":"html","html":"<p><strong><br>\nLoading module “oracleasm”: failed<br>\n</strong></p>"},{"type":"quote","text":"To investigate such error : one must check /var/log/oracleasm\nCreating /dev/oracleasm mount point: /dev/oracleasm\nLoading module \"oracleasm\": failed\nUnable to load module \"oracleasm\"\nLoading module \"oracleasm\": failed\nUnable to load module \"oracleasm\"\nLoading module \"oracleasm\": failed\nUnable to load module \"oracleasm\"\nLoading module \"oracleasm\": failed\nUnable to load module \"oracleasm\"\nLoading module \"oracleasm\": failed\nUnable to load module \"oracleasm\"\nLoading module \"oracleasm\": failed\nUnable to load module \"oracleasm\"\nCleaning any stale ASM disks...\nLoading module \"oracleasm\": failed\nUnable to load module \"oracleasm\"\nLoading module \"oracleasm\": failed\nUnable to load module \"oracleasm\"\nCreating /dev/oracleasm mount point: /dev/oracleasm\nLoading module \"oracleasm\": failed\nUnable to load module \"oracleasm\"\nLoading module \"oracleasm\": failed\nUnable to load module \"oracleasm\"\nReloading disk partitions: done\nCleaning any stale ASM disks...\nScanning system for ASM disks...\noracleasm-read-label: Unable to open device \"/dev/dm-5\": No such file or directory\noracleasm-read-label: Unable to open device \"/dev/dm-5\": No such file or directory\noracleasm-read-label: Unable to open device \"/dev/dm-5\": No such file or directory\noracleasm-read-label: Unable to open device \"/dev/dm-5\": No such 