SELECT gen_random_uuid(), 'page', 90, 'apache-has-not-been-designed-to-serve-pages-while-running-as-root', 'Apache has not been designed to serve pages while running as root.', 'Error –> Process (index=1,uid=499219628,pid=17071) failed to start a managed process after the maximum retry limit Log: /d04/applclone/inst/apps/VINTEST_server/logs/ora/10.1.3/opmn/HTTP_Server~1.log 13/01/25 12:33:02 Start process ——–…', '{"type":"none"}'::jsonb, '[{"type":"quote","text":"Error\n--> Process (index=1,uid=499219628,pid=17071)\nfailed to start a managed process after the maximum retry limit\nLog:\n/d04/applclone/inst/apps/VINTEST_server/logs/ora/10.1.3/opmn/HTTP_Server~1.log\n13/01/25 12:33:02 Start process\n--------\n/d04/applclone/inst/apps/VINTEST_server/ora/10.1.3/Apache/Apache/bin/apachectl startssl: execing httpd\nError: Apache has not been designed to serve pages while\nrunning as root. There are known race conditions that\nwill allow any local user to read any file on the system.\nIf you still desire to serve pages as root then\nadd -DBIG_SECURITY_HOLE to the EXTRA_CFLAGS line in your\nsrc/Configuration file and rebuild the server. It is\nstrongly suggested that you instead modify the User\ndirective in your httpd.conf file to list a non-root\nuser.\n112,2-9 Bot\n[applclone@server scripts]$ ./adopmnctl.sh status\nYou are running adopmnctl.sh version 120.6\nChecking status of OPMN managed processes...\nProcesses in Instance: VINTEST_server.server.csacons.com\n---------------------------------+--------------------+---------+---------\nias-component | process-type | pid | status\n---------------------------------+--------------------+---------+---------\nOC4JGroup:default_group | OC4J:oafm | 13120 | Alive\nOC4JGroup:default_group | OC4J:forms | 13025 | Alive\nOC4JGroup:default_group | OC4J:oacore | 12907 | Alive\nHTTP_Server | HTTP_Server | N/A | Down\nadopmnctl.sh: exiting with status 0\nadopmnctl.sh: check the logfile /d04/applclone/inst/apps/VINTEST_server/logs/appl/admin/log/adopmnctl.txt for more information ...\n[applclone@server scripts]$"},{"type":"quote","text":"Edit context file using context editor for s_appsuser and s_appsgroup variables with correct values and then re-run autoconfig."}]'::jsonb,
  NULL, 'csayantan', '{}'::text[], '{}'::text[], '{"title":"Apache has not been designed to serve pages while running as root.","description":"Error –> Process (index=1,uid=499219628,pid=17071) failed to start a managed process after the maximum retry limit Log…","canonical":"https://cadentic.dev/oracle-apps-r12/apache-has-not-been-designed-to-serve-pages-while-running-as-root","noindex":false}'::jsonb, 'draft', NULL,
