SELECT gen_random_uuid(), 'page', 0, 'zone-in-sun-os-5-11-solaris-11-1', 'Zone in Sun OS 5.11 – Solaris 11.1', 'Creation Of Zone in Solaris 11 and Crating System profile. ping google.com ping 8.8.8.8 host -t csaconsultants.in ifconfig ifconfig up ifconfig -a zfs create -o mountpoint=/zones rpool/zones zfs list zfs list rpool/zones dladm create-vnic -l net0 vnic1 dladm init 6 dterm ipadm tail -f…', '{"type":"none"}'::jsonb, '[{"type":"quote","text":"Creation Of Zone in Solaris 11 and Crating System profile."},{"type":"quote","text":"ping google.com\nping 8.8.8.8\nhost -t csaconsultants.in\nifconfig\nifconfig up\nifconfig -a\nzfs create -o mountpoint=/zones rpool/zones\nzfs list\nzfs list rpool/zones\ndladm create-vnic -l net0 vnic1\ndladm\ninit 6\ndterm\nipadm\ntail -f /var/log/zones/zoneadm.20130131T073250Z.zone1.install\nzoneadmin list -cv\nzoneadm list -cv\nzoneadm list -cv\nipadm\nping 192.168.1.51\nssh 192.168.1.51\nscp 192.168.1.51:/ .\nzoneadm list -cv\nzlogin -C zone1\nls -larth\nvim .bash_history\nifconfig -a\nvim .bash_history\nzonecfg -l\nzonecfg -z zone1\nvim zone.txt\nvi zone.txt\ncat zone.txt\ncat zone.txt\nzoneadm list -cv\nvi zone.txt\nsysconfig create-profile -o /zone1-profile.xml\nzoneadm -z zone1 /zone1-profile.xml\nzoneadm -z zone1 install -c /zone1-profile.xml\nzoneadm -z zone1 boot\nzoneadm list -cv\nhostname\nipadm\nzoneadm list -vi\nzoneadm -z uninstall zone1\nzoneadm -z uninstall /zones/zone1\nzoneadm -z zone1 uninstall\nzoneadm list -vi\nzonecfg -z zone1 delete\nzoneadm list -cv\nzoneadm list -vi\nls\nls\nscp ../zone_commands.txt 192.168.1.51:/root/\nscp ../zone_commands.txt 192.168.1.51:/root\nscp 192.168.1.51:/root zone_commands.txt\nscp -p ../zone_commands.txt 192.168.1.51:/root/\nscp ../zone_commands.txt 192.168.1.51:/root/\nssh 192.168.1.51\nipadm\ninit 6\nzlogin -C zone1\nvi zone_commands.txt\nvi zone_commands.txt\nll\nls"},{"type":"quote","text":"root@solaris:~# zonecfg -l\nzonecfg: illegal option -- l\nusage: zonecfg help\nzonecfg -z