SELECT gen_random_uuid(), 'page', 580, 'qmail-installation', 'Qmail Installation', 'qmail Qmail Downloads rpm -Uhv rpmforge-release-0.3.6-1.el5.rf.i386.rpm yum install gcc* yum install openldap* yum install zlib* yum install glib yum install gdbm* yum install openssl-devel yum install php* Qmail Users / groups mkdir -p /var/qmail groupadd nofiles useradd -g nofiles -d…', '{"type":"none"}'::jsonb, '[{"type":"quote","text":"qmail\nQmail Downloads\nrpm -Uhv rpmforge-release-0.3.6-1.el5.rf.i386.rpm\nyum install gcc*\nyum install openldap*\nyum install zlib*\nyum install glib\nyum install gdbm*\nyum install openssl-devel\nyum install php*\nQmail Users / groups\nmkdir -p /var/qmail\ngroupadd nofiles\nuseradd -g nofiles -d /var/qmail/alias -s /sbin/nologin -p''*'' alias\nuseradd -g nofiles -d /var/qmail -s /sbin/nologin -p''*'' qmaild\nuseradd -g nofiles -d /var/qmail -s /sbin/nologin -p''*'' qmaill\nuseradd -g nofiles -d /var/qmail -s /sbin/nologin -p''*'' qmailp\ngroupadd qmail\nuseradd -g qmail -d /var/qmail -s /sbin/nologin -p''*'' qmailq\nuseradd -g qmail -d /var/qmail -s /sbin/nologin -p''*'' qmailr\nuseradd -g qmail -d /var/qmail -s /sbin/nologin -p''*'' qmails\ngroupadd vmail\nuseradd -g vmail -s /bin/true vmail\nQmail Compilation\nmkdir -p /var/qmail\nmkdir /usr/src/qmail\ncd /usr/src/qmail\ntar xvzf /downloads/qmailrocks/qmail-1.03.tar.gz\ncd qmail-1.03\ncd /downloads\ngzip -d qmail-ldap-1.03-20060201.patch.gz\ncd /usr/src/qmail/qmail-1.03\npatch -p1 concurrencyincoming\necho 255 > concurrencyremote\necho ./Maildir/ > defaultdelivery\necho kortekelectronics.com > defaultdomain\necho 10000 > defaultquotacount\necho 10000000 > defaultquotasize\necho /var/qmail/bin/dirmaker > dirmaker\necho dc=kortekelectronics,dc=com > ldapbasedn\necho 0 > ldapcluster\nid -g vmail > ldapgid\necho cn=manager,dc=kortekelectronics,dc=com > ldaplogin\necho /home/vmail > ldapmessagestore\necho qmailUser > ldapobjectclass\necho p4mail1server > ldappassword\necho 127.0.0.1 > ldapserver\nid -u vmail > ldapuid\necho mail1.kortekelectronics.com > me\necho 127.:allow,NOPBS=\"\" :deny > qmail-pop3d.rules\necho 800000000 > qmail-smtpd-softlimit\necho 3 > qmail-start-loglevel\necho 3 > qmail-pop3d-loglevel\necho 800000000 > qmail-pop3d-softlimit\necho \" Your mail quota is overflowing, check it out\" > quotawarning\necho kortekelectronics.com >> rcpthosts\necho mail1.kortekelectronics.com >> rcpthosts\nln -s rcpthosts locals\necho admin@kortekelectronics.com > /var/qmail/alias/.qmail-root\necho admin@kortekelectronics.com > /var/qmail/alias/.qmail-postmaster\necho admin@kortekelectronics.com > /var/qmail/alias/.qmail-mailer-daemon\nln -s /var/qmail/alias/.qmail-root /var/qmail/alias/.qmail-anonymous\nchmod 644 /var/qmail/alias/.qmail*\ncd /var/qmail\nvi bin/dirmaker\n-------------------------------------------------------------------------------------\n#!/bin/sh\necho ''----------------------------------------------'' >> /tmp/dirmaker\ndate >> /tmp/dirmaker\necho $1 >> /tmp/dirmaker\nid >> /tmp/dirmaker\nmkdir --parents -m 700 -p $1/Maildir\nmkdir --parents -m 700 -p $1/Maildir/tmp\nmkdir --parents -m 700 -p $1/Maildir/cur\nmkdir --parents -m 700 -p $1/Maildir/new\nchown -R vmail:vmail $1\n---------------------------------------------------------------------------------------\nvi rc\n---------------------------------------------------------------------------------------\n#!/bin/sh\nQLOG=\"`cat /var/qmail/control/qmail-start-loglevel`\"\nDEFD=\"`cat /var/qmail/control/defaultdelivery`\"\nexec env - PATH=\"/var/qmail/bin:$PATH\" LOGLEVEL=\"$QLOG\" qmail-start \"$DEFD\"\n--------------------------------------------------------------------------------------------\nchmod 755 rc bin/dirmaker\nUCSPI-TCP / Daemontools Install\ncd /usr/src/qmail\ntar zxvf /downloads/qmailrocks/ucspi-tcp-0.88.tar.gz\ncd ucspi-tcp-0.88\npatch < /downloads/qmailrocks/patches/ucspi-tcp-0.88.errno.patch\nmake && make setup check\nmkdir -p /package\nchmod 1755 /package\ncd /package\ntar zxvf /downloads/qmailrocks/daemontools-0.76.tar.gz\ncd /package/admin/daemontools-0.76/src\npatch &1\n---------------------------------------------------------------------------------------------\nvi qmail-smtpd/log/run\n---------------------------------------------------------------------------------------------\n#!/bin/sh\nPATH=/var/qmail/bin:/usr/local/bin:/usr/bin:/bin\nexport PATH\nexec /usr/local/bin/setuidgid qmaill /usr/local/bin/multilog t s10000000 n20 /var/log/qmail/qmail-smtpd 2>&1\n---------------------------------------------------------------------------------------------\nvi qmail-send/run\n---------------------------------------------------------------------------------------------\n#!/bin/sh\nexec /var/qmail/rc\n---------------------------------------------------------------------------------------------\nvi qmail-send/log/run\n---------------------------------------------------------------------------------------------\n#!/bin/sh\nexec /usr/local/bin/setuidgid qmaill /usr/local/bin/multilog t s10000000 n20 /var/log/qmail/qmail-send 2>&1\n----------------------------------------------------------------------------------------------\nvi qmail-pop3d/run\n----------------------------------------------------------------------------------------------\n#!/bin/sh\nIP=`head -1 /var/qmail/control/me`\nLL=`head -1 /var/qmail/control/qmail-pop3d-loglevel`\nSL=`head -1 /var/qmail/control/qmail-pop3d-softlimit`\nexec \\\nenv LOGLEVEL=$LL \\\nsoftlimit -m $SL \\\n/usr/local/bin/tcpserver -v -R -H -l 0 0 pop3 \\\n/var/qmail/bin/qmail-popup $IP \\\n/var/qmail/bin/tcp-env \\\n/var/qmail/bin/auth_pop \\\n/var/qmail/bin/qmail-pop3d Maildir 2>&1\nvi qmail-pop3d/log/run\n--------------------------------------------------------------\n#!/bin/sh\nPATH=/var/qmail/bin:/usr/local/bin:/usr/bin:/bin\nexport PATH\nexec setuidgid qmaill multilog t s10000000 n20 /var/log/qmail/qmail-pop3d 2>&1 --------------------------------------------------------------\nvi /etc/tcp.smtp\n---------------------------------------------------------------------------------------------------\n127.:allow,RELAYCLIENT=\"\",MAXRCPTCOUNT=\"25\"\n10.:allow,RELAYCLIENT=\"\",MAXRCPTCOUNT=\"25\"\n#10.:allow,RELAYCLIENT=\"\",SMTPAUTH=\"\",AUTHREQUIRED=\"\",SENDERCHECK=\"\",LOGLEVEL=\"3\",RCPTCHECK=\"\",NOPBS=\"\",SANITYCHECK=\"\",BLCKRELAYPRBE=\"\"\n---------------------------------------------------------------------------------------------------\ncd /var/qmail\nrsync -avur /downloads/qmailrocks/scripts/finalize/qmailctl bin/.\nln -s /var/qmail/bin/qmailctl /usr/bin\nConfiguration changes\nvi /usr/local/etc/imapd\n-------------------------------------------------------------------------------------------------------\nIMAPDSTART=YES\n-------------------------------------------------------------------------------------------------------\nvi /usr/local/etc/imapd-ssl\n-------------------------------------------------------------------------------------------------------\nIMAPDSSLSTART=YES\nTLS_CERTFILE=/usr/local/share/imapd.pem\n-------------------------------------------------------------------------------------------------------\nvi /usr/local/etc/authlib/authdaemonrc\n-------------------------------------------------------------------------------------------------------\nauthmodulelist=\"authldap\"\nauthmodulelistorig=\"authldap\"\n-------------------------------------------------------------------------------------------------------\nvi /usr/local/etc/authlib/authldaprc\n-------------------------------------------------------------------------------------------------------\nLDAP_SERVER localhost\nLDAP_PORT 389\nLDAP_PROTOCOL_VERSION 3\nLDAP_BASEDN dc=kortekelectronics,dc=com\nLDAP_BINDDN cn=manager, dc=kortekelectronics,dc=com\nLDAP_BINDPW p4mail1server\nLDAP_TIMEOUT 5\nLDAP_AUTHBIND 1\nLDAP_MAIL uid\nLDAP_GLOB_UID vmail\nLDAP_GLOB_GID vmail\nLDAP_HOMEDIR mailMessageStore\nLDAP_MAILROOT /home/vmail\nLDAP_DEFAULTDELIVERY defaultDelivery\nLDAP_FULLNAME mail.kortekelectronics.com\nLDAP_CLEARPW clearPassword\nLDAP_CRYPTPW userPassword\n#LDAP_CRYPTPW sambaLMPassword\nLDAP_DEREF never\nLDAP_TLS 0\n---------------------------------------------------------------------------------------------------\ncp /usr/local/libexec/imapd.rc /etc/rc.d/init.d/imap\ncp /usr/local/libexec/imapd-ssl.rc /etc/rc.d/init.d/imaps\nvi /etc/rc.local\n( Add following line )\n----------------------------------------------------------------------------------------------------\n/etc/rc.d/init.d/imap start\n/etc/rc.d/init.d/imaps start\n-----------------------------------------------------------------------------------------------------\n/usr/local/sbin/authdaemond stop\n/usr/local/sbin/authdaemond start\n/etc/rc.d/init.d/imap stop\n/etc/rc.d/init.d/imaps stop\n/etc/rc.d/init.d/imap start\n/etc/rc.d/init.d/imaps start\nqmailctl cdb\nphpldapadmin\nyum install php -y\nyum install php-ldap -y\ncd /downloads\nwget http://downloads.sourceforge.net/project/phpldapadmin/phpldapadmin-php5/1.2.0.5/phpldapadmin-1.2.0.5.tgz?use_mirror=nchc\ntar zxvf phpldapadmin-1.2.0.5.tgz\nmv phpldapadmin-1.2.0.5 /var/www/html/phpldapadmin\ncd /var/www/html/phpldapadmin\nmv config/config.php.example config/config.php\nmkdir templates/creation/old templates/modification/old\nmv templates/creation/* templates/creation/old/\nmv templates/modification/* templates/modification/old/\nvi /etc/php.ini\nmemory_limit = 128M\nWebmail\ncd /downloads\nwget http://downloads.sourceforge.net/project/squirrelmail/stable/1.4.20/squirrelmail-1.4.20.tar.gz?use_mirror=space\ntar zxvf squirrelmail-1.4.20.tar.gz\nmv squirrelmail-1.4.20 /var/www/html/webmail\ncd /var/www/html/webmail\nmkdir /var/sqattachements\nchown -R apache:apache /var/sqattachements\nchown -R apache:apache data\ncd config\n./conf.pl"}]'::jsonb,
  NULL, 'csayantan', '{}'::text[], '{}'::text[], '{"title":"Qmail Installation","description":"qmail Qmail Downloads rpm -Uhv rpmforge-release-0.3.6-1.el5.rf.i386.rpm yum install gcc* yum install openldap* yum install zlib* yum install glib yum install…","canonical":"https://cadentic.dev/linux-rhel5-basics/qmail-installation","noindex":false}'::jsonb, 'draft', NULL,
